def load_all_recent_bot_messages():
    """Восстанавливает _recent_bot_message_ids из БД при старте бота - без
    этого после каждого редеплоя старые сообщения, отправленные в прошлых
    запусках, навсегда "зависали" бы в чатах (см. комментарий выше)."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT chat_id, message_id FROM recent_bot_messages ORDER BY id ASC')
        rows = cursor.fetchall()
        conn.close()
        for chat_id, message_id in rows:
            _recent_bot_message_ids.setdefault(chat_id, []).append(message_id)
        logger.info(f"✅ Восстановлена очередь последних сообщений для {len(_recent_bot_message_ids)} чатов из БД")
    except Exception as e:
        logger.error(f"❌ Не удалось восстановить очередь последних сообщений: {e}")

# ДОБАВЛЕНО 22.09.2026 (см. комментарий у CREATE TABLE last_reply_keyboard_messages
# в init_db) - персистентность для _last_reply_keyboard_msg_id, той же
# схемой, что recent_bot_messages выше (save/load переживают рестарт
# Railway). По одной строке на чат - INSERT ... ON CONFLICT UPDATE, старое
# значение просто перезаписывается новым (нам нужен только последний id).
def save_last_reply_keyboard_message(chat_id, message_id):
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO last_reply_keyboard_messages (chat_id, message_id, updated_at) VALUES (?, ?, CURRENT_TIMESTAMP) '
            'ON CONFLICT(chat_id) DO UPDATE SET message_id=excluded.message_id, updated_at=excluded.updated_at',
            (chat_id, message_id)
        )
        conn.commit()
        conn.close()
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить последнее menu-сообщение чата {chat_id}: {e}")

def load_all_last_reply_keyboard_messages():
    """Восстанавливает _last_reply_keyboard_msg_id (и _last_reply_keyboard_sent_at
    - см. комментарий у REPLY_KEYBOARD_STALE_HOURS выше по файлу) из БД при
    старте - без этого после каждого редеплоя сообщение с меню, отправленное
    в прошлом запуске, никогда бы не удалялось следующим таким сообщением
    (см. комментарий у CREATE TABLE last_reply_keyboard_messages в init_db)."""
    try:
        init_db()
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT chat_id, message_id, updated_at FROM last_reply_keyboard_messages')
        rows = cursor.fetchall()
        conn.close()
        for chat_id, message_id, updated_at in rows:
            _last_reply_keyboard_msg_id[chat_id] = message_id
            try:
                _last_reply_keyboard_sent_at[chat_id] = datetime.strptime(updated_at, '%Y-%m-%d %H:%M:%S')
            except Exception:
                pass  # старая строка без парсибельного updated_at - просто не заполняем TTL, кнопка-подстраховка появится раньше срока, не страшно
        logger.info(f"✅ Восстановлены последние menu-сообщения для {len(rows)} чатов из БД")
    except Exception as e:
        logger.error(f"❌ Не удалось восстановить последние menu-сообщения: {e}")

user_state = PersistentUserStateStore()

_flights_data_cache = None
_flights_data_mtime = None

# ИСПРАВЛЕНО 20.09.2026 (жалоба - "надо чтобы бот давал последние загруженные
# данные, а не нули, даже если Yandex заблокировал ключ"): fetch_yandex_data.py
# уже старается не затирать flights_data.json нулями при сбое ОДНОГО запуска
# (см. previous_result в fetch_yandex_data.py), но это не спасает первый
# прогон после переезда на новый /data volume (там ещё нет старого файла,
# затирать нечем) и любой другой случай, когда в файле УЖЕ оказались нули
# (как случилось 20.09.2026 из-за блокировки ключа Яндексом на 501/500
# запросов). Поэтому здесь, на стороне бота (а не сборщика данных), держим
# ОТДЕЛЬНЫЙ файл на постоянном volume с последним НЕПУСТЫМ списком прилётов
# по каждому аэропорту - и если свежий flights_data.json вдруг говорит "0
# рейсов" для аэропорта, который не закрыт, подставляем сюда этот последний
# хороший снепшот вместо нулей (с пометкой stale=True, чтобы при желании
# можно было показать водителю "данные могут быть не совсем свежие").
LAST_GOOD_FLIGHTS_FILE = os.path.join(DATA_DIR, 'last_good_flights.json')


def _load_last_good_flights():
    try:
        with open(LAST_GOOD_FLIGHTS_FILE, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception:
        return {}


def _save_last_good_flights(snapshot):
    try:
        with open(LAST_GOOD_FLIGHTS_FILE, 'w', encoding='utf-8') as f:
            json.dump(snapshot, f, ensure_ascii=False, indent=2)
    except Exception as e:
        logger.error(f"❌ Не удалось сохранить {LAST_GOOD_FLIGHTS_FILE}: {e}")


def _apply_last_good_flights_fallback(data):
    """Мутирует data['airports'][icao]['arrivals'] на месте: если пусто и
    аэропорт не закрыт - подставляет последний непустой снепшот. Обновляет
    и сам снепшот на диске, когда встречает свежие непустые данные."""
    if not data or 'airports' not in data:
        return data

    last_good = _load_last_good_flights()
    changed = False

    for icao, airport_info in data.get('airports', {}).items():
        if airport_info.get('closed'):
            continue
        arrivals = airport_info.get('arrivals') or []
        if arrivals:
            # Свежие данные реально есть - запоминаем их как новый "последний хороший" снепшот
            last_good[icao] = {
                'arrivals': arrivals,
                'saved_at': data.get('generated_at'),
            }
            changed = True
        else:
            # Пусто в свежем файле - если есть сохранённый непустой снепшот, подставляем его
            fallback = last_good.get(icao)
            if fallback and fallback.get('arrivals'):
                airport_info['arrivals'] = fallback['arrivals']
                airport_info['stale'] = True
                airport_info['stale_since'] = fallback.get('saved_at')
                logger.warning(
                    f"⚠️ {icao}: свежие данные пустые (0 прилётов) - подставляю последний "
                    f"непустой снепшот от {fallback.get('saved_at', '?')} ({len(fallback['arrivals'])} рейсов)"
                )
            else:
                # ДОБАВЛЕНО 21.09.2026 (диагностика бага "весь день 0% по
                # всем аэропортам, хотя должен был сработать fallback") -
                # раньше в этом случае просто молчали, из-за чего было
                # невозможно понять по логам, ПОЧЕМУ fallback не сработал:
                # то ли last_good_flights.json пуст/отсутствует, то ли в
                # нём просто нет записи для конкретно этого icao (например,
                # Yandex ни разу за всё время работы бота не прислал по
                # нему непустой ответ). Теперь явно логируем оба случая.
                if not last_good:
                    logger.warning(
                        f"⚠️ {icao}: свежие данные пустые (0 прилётов), fallback НЕ применён - "
                        f"last_good_flights.json пуст или отсутствует на диске ({LAST_GOOD_FLIGHTS_FILE})"
                    )
                else:
                    logger.warning(
                        f"⚠️ {icao}: свежие данные пустые (0 прилётов), fallback НЕ применён - "
                        f"для этого аэропорта ещё ни разу не сохранялся непустой снепшот "
                        f"(в last_good_flights.json сейчас {len(last_good)} других аэропортов: "
                        f"{sorted(last_good.keys())})"
                    )

    if changed:
        _save_last_good_flights(last_good)

    return data


def load_flights_data():
    """Загружает flights_data.json (генерируется fetch_yandex_data.py локально).
    Кэширует в памяти, перечитывает только если файл изменился на диске.
    Подставляет последний непустой снепшот вместо нулей, если свежие данные
    для какого-то аэропорта пустые (см. _apply_last_good_flights_fallback)."""
    global _flights_data_cache, _flights_data_mtime
    try:
        mtime = os.path.getmtime(FLIGHTS_DATA_FILE)
        if _flights_data_cache is not None and mtime == _flights_data_mtime:
            return _flights_data_cache

        with open(FLIGHTS_DATA_FILE, 'r', encoding='utf-8') as f:
            data = json.load(f)

        generated_at = datetime.fromisoformat(data['generated_at'])
        age_hours = (datetime.now() - generated_at).total_seconds() / 3600
        if age_hours > FLIGHTS_DATA_MAX_AGE_HOURS:
            logger.warning(f"⚠️ flights_data.json устарел ({age_hours:.1f}ч), но всё равно используем")

        data = _apply_last_good_flights_fallback(data)

        _flights_data_cache = data
        _flights_data_mtime = mtime
        return data
    except FileNotFoundError:
        logger.warning("⚠️ flights_data.json не найден - запусти fetch_yandex_data.py локально. Использую запасные данные.")
        return None
    except Exception as e:
        logger.error(f"❌ Ошибка чтения flights_data.json: {e}")
        return None

