def format_user_contact(user):
    """Контакт для связи между водителями - ник через @ (как просил
    пользователь). У части аккаунтов Telegram ник не задан вообще -
    запасной вариант: имя + числовой ID (по нему тоже можно найти человека
    через пересылку сообщения, хоть и не так напрямую, как по нику)."""
    if user.username:
        return f"@{user.username}"
    name = escape_md(user.full_name or 'без имени')
    return f"{name} (ник не задан, ID: {user.id})"

def create_shared_order(sender_id, sender_contact, city, category, pickup, dropoff, price_from, price_to, car_class,
                         passengers, client_phone=None, loader_needed=None, cargo_length_cm=None, cargo_width_cm=None,
                         cargo_height_cm=None, cargo_volume_m3=None, cargo_weight_kg=None,
                         commission_from=None, commission_to=None):
    """price_from/price_to - диапазон стоимости поездки (по прямой просьбе
    пользователя, 22.09.2026 - "нужно везде сделать поле цена от и до, но
    необязательно чтобы обе цены были указаны"), commission_from/
    commission_to - тот же диапазон для "моя комиссия" (НЕобязательное поле
    целиком). Старая колонка price TEXT NOT NULL заполняется для обратной
    совместимости комбинированным значением - см. price_compat ниже."""
    init_db()
    if price_from and price_to:
        price_compat = f"{price_from}-{price_to}"
    else:
        price_compat = price_from or price_to or ''
    conn = get_db_connection()
    cursor = conn.execute(
        'INSERT INTO shared_orders (sender_id, sender_contact, city, category, pickup, dropoff, price, price_from, '
        'price_to, car_class, passengers, client_phone, loader_needed, cargo_length_cm, cargo_width_cm, '
        'cargo_height_cm, cargo_volume_m3, cargo_weight_kg, commission_from, commission_to) '
        'VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)',
        (sender_id, sender_contact, city, category, pickup, dropoff, price_compat, price_from, price_to, car_class,
         passengers, client_phone, loader_needed, cargo_length_cm, cargo_width_cm, cargo_height_cm, cargo_volume_m3,
         cargo_weight_kg, commission_from, commission_to)
    )
    order_id = cursor.lastrowid
    conn.commit()
    conn.close()
    return order_id

_SHARED_ORDER_FIELDS = ['order_id', 'sender_id', 'sender_contact', 'city', 'category', 'pickup', 'dropoff',
                         'price', 'car_class', 'passengers', 'status', 'accepted_by', 'accepted_by_contact',
                         'created_at', 'accepted_at', 'client_phone', 'cargo_length_cm', 'cargo_width_cm',
                         'cargo_height_cm', 'cargo_volume_m3', 'cargo_weight_kg', 'loader_needed',
                         'sender_confirmed_at', 'accepter_confirmed_at',
                         'price_from', 'price_to', 'commission_from', 'commission_to']

def format_share_order_price_range(from_val, to_val, label='Стоимость', emoji='💰'):
    """Универсальный форматтер для полей-диапазонов "от/до" - цена поездки и
    "моя комиссия" (по прямой просьбе пользователя, 22.09.2026: "нужно везде
    сделать поле цена от и до, но необязательно чтобы обе цены были указаны -
    достаточно одной цифры"). Если задана только ОДНА граница - показываем её
    БЕЗ "от"/"до" (подтверждено пользователем явно, а не "от 1500 ₽"), если
    заданы ОБЕ - диапазоном "1500–2000 ₽", если НИ ОДНОЙ - пустая строка
    (используется в условных строках, как у пассажиров/грузчика/груза).
    Переиспользуется и для price, и для commission, чтобы не дублировать
    логику форматирования от/до."""
    from_val = from_val if from_val not in (None, '') else None
    to_val = to_val if to_val not in (None, '') else None
    if from_val is None and to_val is None:
        return ""
    if from_val is not None and to_val is not None:
        value = f"{from_val}–{to_val}"
    else:
        value = str(from_val if from_val is not None else to_val)
    return f"{emoji} {label}: {value} ₽\n"

def get_shared_order(order_id):
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(f'SELECT {", ".join(_SHARED_ORDER_FIELDS)} FROM shared_orders WHERE order_id = ?', (order_id,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    return dict(zip(_SHARED_ORDER_FIELDS, row))

def is_shared_order_expired(order):
    """SHARED_ORDER_EXPIRY_HOURS (решение пользователя - 1 час) с момента
    создания. created_at хранится в UTC (SQLite CURRENT_TIMESTAMP), поэтому
    сравниваем с datetime.now(UTC), а не с местным временем сервера."""
    try:
        created = datetime.strptime(order['created_at'], '%Y-%m-%d %H:%M:%S').replace(tzinfo=ZoneInfo('UTC'))
    except Exception:
        return False  # не смогли распарсить - не считаем протухшим, чтобы не терять заказ на пустом месте
    return datetime.now(ZoneInfo('UTC')) - created > timedelta(hours=SHARED_ORDER_EXPIRY_HOURS)

def try_accept_shared_order(order_id, accepted_by, accepted_by_contact):
    """Атомарно "забирает" заказ - условие status='open' прямо в WHERE
    гарантирует, что при одновременном нажатии "Принять" двумя водителями
    выиграет только тот, чей UPDATE применится первым (SQLite сериализует
    запись на уровне файла БД) - остальные получат rowcount=0 и поймут, что
    опоздали, без отдельных блокировок в коде бота."""
    init_db()
    conn = get_db_connection()
    cursor = conn.execute(
        "UPDATE shared_orders SET status='accepted', accepted_by=?, accepted_by_contact=?, accepted_at=? "
        "WHERE order_id=? AND status='open'",
        (accepted_by, accepted_by_contact, datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S'), order_id)
    )
    conn.commit()
    won = cursor.rowcount == 1
    conn.close()
    return won

def expire_shared_order(order_id):
    init_db()
    conn = get_db_connection()
    conn.execute("UPDATE shared_orders SET status='expired' WHERE order_id=? AND status='open'", (order_id,))
    conn.commit()
    conn.close()

def increment_completed_orders(user_id):
    """Счётчик выполненных заказов у ПРИНЯВШЕГО заказ водителя (по прямой
    просьбе пользователя, 22.09.2026 - "пока без системы оценивания", просто
    число). driver_profiles может ещё не иметь строки для этого user_id
    (профиль не заполнялся) - ON CONFLICT ... DO UPDATE (тот же паттерн, что
    save_driver_profile выше) создаёт строку с 1 или увеличивает существующую."""
    try:
        init_db()
        conn = get_db_connection()
        conn.execute(
            'INSERT INTO driver_profiles (user_id, completed_orders_count) VALUES (?, 1) '
            'ON CONFLICT(user_id) DO UPDATE SET completed_orders_count = COALESCE(completed_orders_count, 0) + 1',
            (user_id,)
        )
        conn.commit()
        cursor = conn.execute('SELECT completed_orders_count FROM driver_profiles WHERE user_id=?', (user_id,))
        row = cursor.fetchone()
        conn.close()
        return row[0] if row else None
    except Exception as e:
        logger.error(f"❌ Не удалось увеличить счётчик выполненных заказов для {user_id}: {e}")
        return None

def confirm_shared_order_done(order_id, is_sender):
    """Отмечает подтверждение выполнения заказа. ИЗМЕНЕНО 22.09.2026 (прямая
    просьба пользователя - "засчитывается только у того, кто заказ принял...
    тот, кто его дал - он ему не нужен"): взаимное подтверждение убрано,
    остался только accepter_confirmed_at (is_sender всегда False у
    единственного вызывающего - order_done_callback; параметр оставлен для
    совместимости сигнатуры/на случай если понадобится другая сторона
    позже). Возвращает (order_after, just_completed) - just_completed=True,
    только если ИМЕННО ЭТО нажатие впервые проставило accepter_confirmed_at
    (защита от повторного тапа, который иначе удвоил бы счётчик)."""
    init_db()
    conn = get_db_connection()
    now = datetime.now(ZoneInfo('UTC')).strftime('%Y-%m-%d %H:%M:%S')
    col = 'sender_confirmed_at' if is_sender else 'accepter_confirmed_at'
    cursor = conn.execute(f"UPDATE shared_orders SET {col}=? WHERE order_id=? AND {col} IS NULL", (now, order_id))
    conn.commit()
    just_completed = cursor.rowcount == 1  # False, если уже подтверждали раньше (повторный тап на кнопку)
    conn.close()
    order = get_shared_order(order_id)
    if just_completed and order and order['status'] != 'completed':
        conn = get_db_connection()
        conn.execute("UPDATE shared_orders SET status='completed' WHERE order_id=?", (order_id,))
        conn.commit()
        conn.close()
        order = get_shared_order(order_id)
    return order, just_completed

