async def show_shared_order_confirmation(message, data, category, city):
    city_name = CITY_DISPLAY_NAMES.get(city, city)
    passengers_line = f"👥 Пассажиров: {data['passengers']}\n" if data.get('passengers') else ""
    loader_line = ""
    if data.get('loader_needed') is not None:
        loader_line = f"🧑‍🔧 Нужен грузчик: {'Да' if data['loader_needed'] == 'yes' else 'Нет'}\n"
    cargo_line = ""
    if any(data.get(k) for k in ('cargo_length_cm', 'cargo_width_cm', 'cargo_height_cm', 'cargo_volume_m3', 'cargo_weight_kg')):
        dims = ''
        if data.get('cargo_length_cm') or data.get('cargo_width_cm') or data.get('cargo_height_cm'):
            dims = f"{data.get('cargo_length_cm') or '?'}×{data.get('cargo_width_cm') or '?'}×{data.get('cargo_height_cm') or '?'} см"
        parts = [p for p in [dims, f"{data['cargo_volume_m3']} м³" if data.get('cargo_volume_m3') else '',
                              f"{data['cargo_weight_kg']} кг" if data.get('cargo_weight_kg') else ''] if p]
        cargo_line = f"📦 Груз: {', '.join(parts)}\n"
    price_line = format_share_order_price_range(data.get('price_from'), data.get('price_to'))
    commission_line = format_share_order_price_range(data.get('commission_from'), data.get('commission_to'), label='Комиссия', emoji='💼')
    text = (
        "*Проверь заказ перед отправкой:*\n\n"
        f"📍 Подача: {escape_md(data['pickup'])}\n"
        f"🏁 Прибытие: {escape_md(data['dropoff'])}\n"
        f"{price_line}"
        f"{commission_line}"
        f"🚘 Класс: {data['car_class']}\n"
        f"{passengers_line}"
        f"{loader_line}"
        f"{cargo_line}"
        f"📱 Телефон клиента: {escape_md(data['client_phone']) if data.get('client_phone') else 'не указан'}\n\n"
        f"_Разошлём водителям города {city_name}. Предложение будет "
        f"действовать {SHARED_ORDER_EXPIRY_HOURS} час, пока кто-то не примет._"
    )
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="📤 ОТПРАВИТЬ ЗАКАЗ", callback_data="order_confirm_send")],
        [InlineKeyboardButton(text="❌ ОТМЕНИТЬ", callback_data="order_confirm_cancel")]
    ])
    await message.answer(text, reply_markup=keyboard, parse_mode='Markdown')

# ==================== ОТДАТЬ ЗАКАЗ (WebApp) ====================
# По просьбе пользователя (21.09.2026) - "🔄 ОТДАТЬ ЗАКАЗ" переведена на
# WebApp-форму. В ОТЛИЧИЕ от погоды/куда ехать/событий/авиа-жд выше, это
# ПЕРСОНАЛЬНОЕ действие (создание реального заказа от имени конкретного
# отправителя), поэтому кнопка в Reply-клавиатуре WebApp НЕ несёт (у
# web_app= прямо в Reply-клавиатуре initData приходит пустым - см. тот же
# факт, установленный для личного кабинета, комментарий у cabinet_row в
# services_keyboard). Вместо этого используется рабочий паттерн личного
# кабинета (open_cabinet_from_menu): по тапу на обычную текстовую кнопку
# бот присылает ОТДЕЛЬНОЕ сообщение с инлайн-кнопкой web_app= - у инлайн-
# кнопок initData передаётся штатно. initData на /share-order/submit
# проверяется СТРОГО (validate_telegram_webapp_init_data, тот же helper,
# что у /cabinet/*) - это запись реальных данных от имени конкретного
# человека. Старый текстовый пошаговый флоу (shared_order_flow и вся
# машина состояний order_draft) НЕ удаляется - остаётся в коде рабочим
# фолбэком (например, если WebApp по какой-то причине не открылся), просто
# кнопка "🔄 ОТДАТЬ ЗАКАЗ" по умолчанию больше не запускает его напрямую.
SHARE_ORDER_WEBAPP_PATH = '/share-order'
SHARE_ORDER_SUBMIT_API_PATH = '/share-order/submit'

def share_order_webapp_html(category=None):
    # category больше не влияет на список классов (см. SHARE_ORDER_CAR_CLASSES) -
    # параметр оставлен для совместимости вызовов, сейчас не используется.
    car_classes_json = json.dumps(SHARE_ORDER_CAR_CLASSES, ensure_ascii=False)
    return """<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Отдать заказ</title>
<script src=\"""" + TG_WEBAPP_JS_PROXY_PATH + """\"></script>
<style>
  :root { color-scheme: light dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; padding: 18px; padding-bottom: max(18px, env(safe-area-inset-bottom, 0px));
    padding-top: max(18px, env(safe-area-inset-top, 0px));
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
    background: #000; color: #fff;
  }
  h1 { font-size: 17px; margin: 0 0 14px; }
  label { display: block; font-size: 12.5px; color: #9a9a9a; margin: 14px 0 6px; }
  input[type=text], input[type=number], input[type=tel] {
    width: 100%; padding: 11px 12px; border-radius: 12px; border: 1px solid rgba(255,255,255,.14);
    background: #141414; color: #fff; font-size: 15px; transition: border-color .15s;
  }
  input:focus { outline: none; border-color: rgba(255,196,0,.55); }
  input::placeholder { color: #666; }
  .pills { display: flex; flex-wrap: wrap; gap: 8px; }
  .pill {
    padding: 8px 14px; border-radius: 20px; background: #1c1c1c; border: 1px solid rgba(255,255,255,.1);
    color: #ccc; font-size: 13.5px; cursor: pointer; transition: transform .12s, background .15s, border-color .15s;
  }
  .pill:active { transform: scale(.94); }
  .pill.active { background: rgba(255,196,0,.16); border-color: #FFC400; color: #FFC400; font-weight: 700; }
  .stepper { display: flex; align-items: center; gap: 14px; }
  .stepper button {
    width: 36px; height: 36px; border-radius: 50%; border: 1px solid rgba(255,255,255,.14);
    background: #1c1c1c; color: #FFC400; font-size: 18px; font-weight: 700; transition: transform .12s;
  }
  .stepper button:active { transform: scale(.88); }
  .stepper span { font-size: 17px; font-weight: 700; min-width: 24px; text-align: center; }
  #submitBtn {
    width: 100%; margin-top: 22px; padding: 14px; border-radius: 14px; border: none;
    background: #FFC400; color: #000; font-size: 15.5px; font-weight: 800; transition: transform .12s;
  }
  #submitBtn:active:not(:disabled) { transform: scale(.97); }
  #submitBtn:disabled { opacity: .5; }
  #err { color: #ff6b6b; font-size: 12.5px; margin-top: 10px; min-height: 16px; }
  #done { display: none; text-align: center; padding: 60px 16px; animation: doneIn .35s ease both; }
  #done .ok { font-size: 44px; margin-bottom: 10px; }
  @keyframes doneIn { from { opacity: 0; transform: scale(.9); } to { opacity: 1; transform: scale(1); } }
  @media (prefers-reduced-motion: reduce) {
    *, *::before, *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }
  }
</style>
</head>
<body>
<div id="form">
  <h1>🔄 Отдать заказ</h1>
  <label>📍 Адрес подачи</label>
  <input type="text" id="pickup" placeholder="Откуда забрать пассажира">
  <label>🏁 Адрес прибытия</label>
  <input type="text" id="dropoff" placeholder="Куда везти">
  <label>💰 Цена от, ₽</label>
  <input type="number" id="priceFrom" placeholder="1500" min="0">
  <label>💰 Цена до, ₽</label>
  <input type="number" id="priceTo" placeholder="2000" min="0">
  <label>💼 Моя комиссия, ₽ (необязательно)</label>
  <div style="display:flex; gap:8px;">
    <input type="number" id="commissionFrom" placeholder="Комиссия от" min="0">
    <input type="number" id="commissionTo" placeholder="Комиссия до" min="0">
  </div>
  <label>🚘 Класс автомобиля</label>
  <div class="pills" id="carClassPills"></div>
  <div id="paxSection">
    <label>👥 Пассажиров (максимум <span id="paxMax">5</span>)</label>
    <div class="stepper">
      <button type="button" id="paxMinus">−</button>
      <span id="paxVal">1</span>
      <button type="button" id="paxPlus">+</button>
    </div>
  </div>
  <div id="loaderSection">
    <label>🧑‍🔧 Нужен грузчик?</label>
    <div class="pills" id="loaderPills">
      <div class="pill" data-v="yes">Да</div>
      <div class="pill" data-v="no">Нет</div>
    </div>
  </div>
  <div id="cargoSection">
    <label>📏 Размеры груза, см (длина / ширина / высота)</label>
    <div style="display:flex; gap:8px;">
      <input type="number" id="cargoLength" placeholder="Длина" min="0">
      <input type="number" id="cargoWidth" placeholder="Ширина" min="0">
      <input type="number" id="cargoHeight" placeholder="Высота" min="0">
    </div>
    <label>📦 Объём груза, м³</label>
    <input type="number" id="cargoVolume" placeholder="Необязательно" min="0" step="0.01">
    <label>⚖️ Вес груза, кг</label>
    <input type="number" id="cargoWeight" placeholder="Необязательно" min="0" step="0.1">
  </div>
  <label>📱 Телефон клиента (необязательно)</label>
  <input type="tel" id="clientPhone" placeholder="Если есть">
  <div id="err"></div>
  <button id="submitBtn">📤 ОТПРАВИТЬ ЗАКАЗ</button>
</div>
<div id="done">
  <div class="ok">✅</div>
  <div id="doneText">Заказ отправлен</div>
</div>
<script>
  const tg = window.Telegram && window.Telegram.WebApp;
  if (tg) { tg.ready(); tg.expand(); }
  if (tg && tg.platform) { fetch('/platform/report', { method: 'POST', headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg.initData || '' }, body: JSON.stringify({ platform: tg.platform }) }).catch(function(){}); }
  const carClasses = """ + car_classes_json + """;
  let carClass = (carClasses[0] || {}).name || '';
  let pax = 1;
  let loaderNeeded = null;  // 'yes' | 'no' | null - обязателен для классов с loader_choice

  function classInfo(name) {
    return carClasses.find(c => c.name === name) || {};
  }
  function classHasPax(name) { return !!classInfo(name).passengers; }
  function classMaxPax(name) { return classInfo(name).max_passengers || 5; }
  function classNeedsLoader(name) { return !!classInfo(name).loader_choice; }
  function classHasCargo(name) { return !!classInfo(name).cargo_dims; }

  function updateSectionsVisibility() {
    document.getElementById('paxSection').style.display = classHasPax(carClass) ? 'block' : 'none';
    document.getElementById('loaderSection').style.display = classNeedsLoader(carClass) ? 'block' : 'none';
    document.getElementById('cargoSection').style.display = classHasCargo(carClass) ? 'block' : 'none';
    if (classHasPax(carClass)) {
      const maxPax = classMaxPax(carClass);
      document.getElementById('paxMax').textContent = maxPax;
      // По прямой просьбе пользователя (22.09.2026) - при переключении с
      // класса на 7 мест на класс с лимитом 5, если текущее значение больше
      // нового максимума, подрезаем его.
      if (pax > maxPax) { pax = maxPax; document.getElementById('paxVal').textContent = pax; }
    }
    if (!classNeedsLoader(carClass)) loaderNeeded = null;
  }

  const pillsEl = document.getElementById('carClassPills');
  pillsEl.innerHTML = carClasses.map(c => '<div class="pill' + (c.name === carClass ? ' active' : '') + '" data-t="' + c.name + '">' + c.name + '</div>').join('');
  pillsEl.querySelectorAll('.pill').forEach(p => p.addEventListener('click', () => {
    carClass = p.dataset.t;
    pillsEl.querySelectorAll('.pill').forEach(x => x.classList.toggle('active', x === p));
    updateSectionsVisibility();
  }));
  updateSectionsVisibility();

  const loaderPillsEl = document.getElementById('loaderPills');
  loaderPillsEl.querySelectorAll('.pill').forEach(p => p.addEventListener('click', () => {
    loaderNeeded = p.dataset.v;
    loaderPillsEl.querySelectorAll('.pill').forEach(x => x.classList.toggle('active', x === p));
  }));

  document.getElementById('paxMinus').addEventListener('click', () => { if (pax > 1) { pax--; document.getElementById('paxVal').textContent = pax; } });
  document.getElementById('paxPlus').addEventListener('click', () => { const maxPax = classMaxPax(carClass); if (pax < maxPax) { pax++; document.getElementById('paxVal').textContent = pax; } });

  document.getElementById('submitBtn').addEventListener('click', async () => {
    const errEl = document.getElementById('err');
    errEl.textContent = '';
    const pickup = document.getElementById('pickup').value.trim();
    const dropoff = document.getElementById('dropoff').value.trim();
    const priceFrom = document.getElementById('priceFrom').value.trim();
    const priceTo = document.getElementById('priceTo').value.trim();
    const commissionFrom = document.getElementById('commissionFrom').value.trim();
    const commissionTo = document.getElementById('commissionTo').value.trim();
    const clientPhone = document.getElementById('clientPhone').value.trim();
    if (!pickup || !dropoff) { errEl.textContent = 'Заполни адреса подачи и прибытия.'; return; }
    // По прямой просьбе пользователя (22.09.2026) - "необязательно чтобы обе
    // цены были указаны - достаточно одной цифры", но хотя бы ОДНА граница
    // цены обязательна (комиссия - полностью необязательна, без этой проверки).
    if ((!priceFrom || Number(priceFrom) <= 0) && (!priceTo || Number(priceTo) <= 0)) { errEl.textContent = 'Укажи хотя бы одну цену - от или до.'; return; }
    if (!carClass) { errEl.textContent = 'Выбери класс автомобиля.'; return; }
    // "Нужен грузчик?" НЕОБЯЗАТЕЛЕН (изменено 22.09.2026 по прямой просьбе
    // пользователя - "сделать произвольно") - можно отправить без ответа,
    // отдельной проверки на отправке больше нет.

    const cargoLength = document.getElementById('cargoLength').value.trim();
    const cargoWidth = document.getElementById('cargoWidth').value.trim();
    const cargoHeight = document.getElementById('cargoHeight').value.trim();
    const cargoVolume = document.getElementById('cargoVolume').value.trim();
    const cargoWeight = document.getElementById('cargoWeight').value.trim();
    const hasCargo = classHasCargo(carClass);

    const btn = document.getElementById('submitBtn');
    btn.disabled = true;
    btn.textContent = 'Отправляю…';
    try {
      const resp = await fetch('""" + SHARE_ORDER_SUBMIT_API_PATH + """', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': (tg ? tg.initData : '') },
        body: JSON.stringify({
          pickup, dropoff, price_from: priceFrom || null, price_to: priceTo || null,
          commission_from: commissionFrom || null, commission_to: commissionTo || null,
          car_class: carClass, passengers: classHasPax(carClass) ? pax : null,
          client_phone: clientPhone || null,
          loader_needed: classNeedsLoader(carClass) ? loaderNeeded : null,
          cargo_length_cm: hasCargo && cargoLength ? cargoLength : null,
          cargo_width_cm: hasCargo && cargoWidth ? cargoWidth : null,
          cargo_height_cm: hasCargo && cargoHeight ? cargoHeight : null,
          cargo_volume_m3: hasCargo && cargoVolume ? cargoVolume : null,
          cargo_weight_kg: hasCargo && cargoWeight ? cargoWeight : null,
        }),
      });
      const data = await resp.json();
      if (!resp.ok || data.error) {
        errEl.textContent = 'Не удалось отправить заказ - попробуй ещё раз.';
        btn.disabled = false;
        btn.textContent = '📤 ОТПРАВИТЬ ЗАКАЗ';
        return;
      }
      document.getElementById('form').style.display = 'none';
      document.getElementById('done').style.display = 'block';
      document.getElementById('doneText').textContent = data.sent > 0
        ? ('Заказ #' + data.order_id + ' отправлен ' + data.sent + ' водителям. Ждём отклика ' + data.expiry_hours + ' час.')
        : ('Заказ #' + data.order_id + ' создан, но сейчас нет других известных водителей поблизости.');
      setTimeout(() => { if (tg) tg.close(); }, 2500);
    } catch (e) {
      errEl.textContent = 'Не удалось отправить заказ - проверь связь и попробуй ещё раз.';
      btn.disabled = false;
      btn.textContent = '📤 ОТПРАВИТЬ ЗАКАЗ';
    }
  });
</script>
</body>
</html>"""

async def handle_share_order_webapp(request):
    return web.Response(
        text=share_order_webapp_html(request.query.get('category', 'taxi')), content_type='text/html',
        headers={'Cache-Control': 'no-store, no-cache, must-revalidate', 'Pragma': 'no-cache'},
    )

async def handle_share_order_submit_api(request):
    """POST {pickup, dropoff, price_from, price_to, commission_from, commission_to,
    car_class, passengers, client_phone} -> создаёт и рассылает заказ. initData ОБЯЗАТЕЛЕН и строго проверяется (тот
    же helper, что у /cabinet/* - validate_telegram_webapp_init_data) - это
    персональное действие от имени конкретного отправителя, без валидной
    подписи неизвестно, кто отправитель. Переиспользует ТЕ ЖЕ функции, что и
    текстовый флоу (create_shared_order/broadcast_shared_order/
    format_user_contact) - никакая бизнес-логика не дублируется."""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    parsed = validate_telegram_webapp_init_data(init_data, BOT_TOKEN) if BOT_TOKEN else None
    if not parsed:
        logger.warning(f"⚠️ /share-order/submit: невалидный initData (len={len(init_data)}) - отдаю 401")
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        tg_user = json.loads(parsed.get('user', '{}'))
        user_id = tg_user.get('id')
    except Exception:
        user_id = None
    if not user_id:
        return web.json_response({'error': 'invalid_init_data'}, status=401)

    state = user_state.get(user_id)
    if not state or 'category' not in state or 'city' not in state:
        return web.json_response({'error': 'no_state'}, status=400)
    category = state['category']
    city = state['city']

    def parse_float(v):
        try:
            return float(v) if v not in (None, '') else None
        except (TypeError, ValueError):
            return None

    try:
        body = await request.json()
        pickup = str(body.get('pickup') or '').strip()
        dropoff = str(body.get('dropoff') or '').strip()
        # По прямой просьбе пользователя (22.09.2026) - цена стала диапазоном
        # "от/до", каждая граница необязательна по отдельности, но хотя бы
        # одна должна быть указана (проверяется ниже). Комиссия - та же
        # схема "от/до", но полностью необязательна.
        price_from_digits = re.sub(r'[^\d]', '', str(body.get('price_from') or ''))
        price_to_digits = re.sub(r'[^\d]', '', str(body.get('price_to') or ''))
        commission_from_digits = re.sub(r'[^\d]', '', str(body.get('commission_from') or ''))
        commission_to_digits = re.sub(r'[^\d]', '', str(body.get('commission_to') or ''))
        car_class = str(body.get('car_class') or '').strip()
        passengers_raw = body.get('passengers')
        passengers = int(passengers_raw) if passengers_raw not in (None, '') else 0
        client_phone = body.get('client_phone')
        client_phone = str(client_phone).strip() if client_phone else None
        loader_needed = body.get('loader_needed')
        loader_needed = loader_needed if loader_needed in ('yes', 'no') else None
        cargo_length_cm = parse_float(body.get('cargo_length_cm'))
        cargo_width_cm = parse_float(body.get('cargo_width_cm'))
        cargo_height_cm = parse_float(body.get('cargo_height_cm'))
        cargo_volume_m3 = parse_float(body.get('cargo_volume_m3'))
        cargo_weight_kg = parse_float(body.get('cargo_weight_kg'))
    except Exception:
        return web.json_response({'error': 'invalid_body'}, status=400)

    class_requires_passengers = SHARE_ORDER_PASSENGERS_BY_CLASS.get(car_class)
    max_pax = SHARE_ORDER_MAX_PASSENGERS_BY_CLASS.get(car_class) or 5
    # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "выбор нужен грузчик
    # или не нужен сделать произвольно"): "Нужен грузчик?" больше НЕ
    # обязателен - loader_needed просто сохраняется, если пришёл, без
    # блокировки отправки при его отсутствии.
    # Серверная валидация (дублирует клиентскую в share_order_webapp_html,
    # но НИКОГДА не доверяем только клиенту) - по прямой просьбе пользователя
    # (22.09.2026): лимит пассажиров по классу.
    if (not pickup or not dropoff or (not price_from_digits and not price_to_digits)
            or car_class not in SHARE_ORDER_CAR_CLASS_NAMES
            or (class_requires_passengers and (passengers <= 0 or passengers > max_pax))):
        return web.json_response({'error': 'invalid_body'}, status=400)

    # tg_user - тот же {id, first_name, username, ...}, что Telegram кладёт в
    # initDataUnsafe.user; собираем "контакт отправителя" в том же формате,
    # что format_user_contact(callback_query.from_user) у текстового флоу.
    sender_contact = tg_user.get('username') and f"@{tg_user['username']}" or tg_user.get('first_name') or str(user_id)
    passengers_str = str(passengers) if class_requires_passengers else ''
    if not SHARE_ORDER_CARGO_DIMS_BY_CLASS.get(car_class):
        # Размеры/объём/вес - только у "Грузовая машина" (по прямой просьбе
        # пользователя, 22.09.2026), у остальных классов игнорируем, даже
        # если клиент вдруг их прислал.
        cargo_length_cm = cargo_width_cm = cargo_height_cm = cargo_volume_m3 = cargo_weight_kg = None
    data = {'pickup': pickup, 'dropoff': dropoff, 'price_from': price_from_digits or None, 'price_to': price_to_digits or None,
            'commission_from': commission_from_digits or None, 'commission_to': commission_to_digits or None,
            'car_class': car_class, 'passengers': passengers_str, 'client_phone': client_phone, 'loader_needed': loader_needed,
            'cargo_length_cm': cargo_length_cm, 'cargo_width_cm': cargo_width_cm, 'cargo_height_cm': cargo_height_cm,
            'cargo_volume_m3': cargo_volume_m3, 'cargo_weight_kg': cargo_weight_kg}
    order_id = create_shared_order(
        user_id, sender_contact, city, category, pickup, dropoff, price_from_digits or None, price_to_digits or None,
        car_class, passengers_str, client_phone, loader_needed, cargo_length_cm, cargo_width_cm, cargo_height_cm,
        cargo_volume_m3, cargo_weight_kg, commission_from_digits or None, commission_to_digits or None,
    )
    try:
        sent = await broadcast_shared_order(order_id, data, city, category, user_id)
    except Exception:
        logger.exception(f"❌ Ошибка рассылки заказа #{order_id} из /share-order/submit")
        sent = 0
    return web.json_response({'ok': True, 'order_id': order_id, 'sent': sent, 'expiry_hours': SHARED_ORDER_EXPIRY_HOURS})

PLATFORM_REPORT_API_PATH = '/platform/report'

async def handle_platform_report_api(request):
    """POST {platform: "ios"|"android"|"tdesktop"|...} - лёгкий эндпоинт,
    вызываемый из ЛЮБОЙ WebApp-страницы этого бота сразу после tg.ready() (по
    прямой просьбе пользователя, 22.09.2026 - "определять платформу
    водителя, чтобы не показывать обе кнопки iOS/Android сразу"). initData
    ОБЯЗАТЕЛЕН и строго проверяется (тот же helper, что у /cabinet/* и
    /share-order/submit) - это персональное действие для конкретного
    пользователя. Сохраняет tg.platform в user_state[user_id]['tg_platform'],
    откуда его потом читает driver_platform_hint() при отправке обычных
    (не-WebApp) сообщений (чаевые, парковка). Не требует наличия
    category/city в state - пользователь может открыть WebApp раньше, чем
    выберет город/категорию."""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    parsed = validate_telegram_webapp_init_data(init_data, BOT_TOKEN) if BOT_TOKEN else None
    if not parsed:
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        tg_user = json.loads(parsed.get('user', '{}'))
        user_id = tg_user.get('id')
    except Exception:
        user_id = None
    if not user_id:
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        body = await request.json()
        platform = str(body.get('platform') or '').strip()
    except Exception:
        platform = ''
    if platform:
        user_state.setdefault(user_id, {})['tg_platform'] = platform
    return web.json_response({'ok': True})

PLATFORM_PROBE_WEBAPP_PATH = '/platform/probe'

def platform_probe_webapp_html():
    """ДОБАВЛЕНО 25.09.2026 (прямая просьба пользователя - "бот понимает с
    какого устройства и предлагает сразу что нужно, а не две кнопки",
    уточнение - захватывать платформу уже "при старте смены") - раньше
    платформа (см. handle_platform_report_api/driver_platform_hint выше)
    узнавалась только КАК ПОБОЧНЫЙ ЭФФЕКТ открытия обычного WebApp (карта/
    Куда ехать/погода и т.д.) - если водитель за смену ни разу не открывал
    ни один из них (например, сразу уехал на заказ), платформа так и
    оставалась неизвестной, и пуши вроде "Похоже, ты припарковался"
    показывали СРАЗУ ОБЕ кнопки (iOS/Android) - см. push_parking_reminder_alert.
    Эта страница - минимальный, максимально незаметный "зонд": открывается
    ОДНИМ тапом по кнопке "📲 Быстрая настройка" в сообщении "СМЕНА НАЧАТА"
    (см. start_shift_and_notify), мгновенно шлёт /platform/report и сразу
    же сама закрывается (Telegram.WebApp.close()) - визуально это доля
    секунды мигания, а не отдельный "экран". Кнопка показывается ТОЛЬКО пока
    driver_platform_hint(user_id) ещё None - как только платформа узнана
    (отсюда или из любого другого WebApp), кнопка при следующих стартах
    смены больше не появляется."""
    return """<!doctype html>
<html lang="ru">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<title>Настройка</title>
<script src=\"""" + TG_WEBAPP_JS_PROXY_PATH + """\"></script>
<style>
  :root { color-scheme: light dark; }
  body { margin: 0; padding: 24px; font: 15px -apple-system, sans-serif; background: #111; color: #ccc; }
</style>
</head>
<body>
готово ✅
<script>
  var tg = window.Telegram ? window.Telegram.WebApp : null;
  if (tg) { tg.ready(); }
  function done() { try { if (tg) tg.close(); } catch (e) {} }
  if (tg && tg.platform) {
    fetch('/platform/report', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'X-Telegram-Init-Data': tg.initData || '' },
      body: JSON.stringify({ platform: tg.platform }),
    }).catch(function(){}).then(done);
    setTimeout(done, 800);  // на случай, если fetch зависнет - страница всё равно закроется
  } else {
    done();
  }
</script>
</body>
</html>"""

async def handle_platform_probe_webapp(request):
    return web.Response(text=platform_probe_webapp_html(), content_type='text/html')

@router.message(lambda message: message.text == "🔄 ОТДАТЬ ЗАКАЗ")
async def start_shared_order(message: types.Message):
    user_id = message.from_user.id
    state = user_state.get(user_id)
    if not state or 'category' not in state:
        await message.answer("Сначала выбери город и категорию!")
        return
    # По просьбе пользователя (21.09.2026) - кнопка теперь открывает WebApp-
    # форму (см. блок "ОТДАТЬ ЗАКАЗ (WebApp)" выше) вместо старого пошагового
    # текстового флоу. Если PUBLIC_URL не задан (локальный/дев-запуск) -
    # остаётся старый текстовый флоу как есть.
    if PUBLIC_URL:
        share_order_url = f"{PUBLIC_URL}{SHARE_ORDER_WEBAPP_PATH}?category={urllib.parse.quote(state['category'])}"
        await message.answer(
            "🔄 ОТДАТЬ ЗАКАЗ",
            reply_markup=InlineKeyboardMarkup(inline_keyboard=[[
                InlineKeyboardButton(text="ВВЕСТИ ДАННЫЕ", web_app=WebAppInfo(url=share_order_url)),
            ]]),
        )
        return
    state['order_draft'] = {'step': 'pickup', 'data': {}}
    await message.answer(SHARED_ORDER_STEP_PROMPTS['pickup'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')

@router.message(lambda message: user_state.get(message.from_user.id, {}).get('order_draft') is not None)
async def shared_order_flow(message: types.Message):
    """Ловит ЛЮБОЙ текст, пока у пользователя активен черновик заказа - должен
    стоять РАНЬШЕ остальных текстовых хендлеров (город/категория и т.п.),
    иначе, например, адрес "Москва, ул. Ленина 1" перехватит select_city."""
    user_id = message.from_user.id
    state = user_state[user_id]
    draft = state['order_draft']
    text = (message.text or '').strip()
    category = state.get('category')
    city = state.get('city')

    if text == "❌ ОТМЕНА":
        state.pop('order_draft', None)
        await message.answer("Черновик заказа отменён.", reply_markup=services_keyboard(category, city, user_id))
        return

    step = draft['step']

    if step == 'pickup':
        if not text:
            await message.answer("Адрес не может быть пустым, попробуй ещё раз:")
            return
        draft['data']['pickup'] = text
        draft['step'] = 'dropoff'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['dropoff'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'dropoff':
        if not text:
            await message.answer("Адрес не может быть пустым, попробуй ещё раз:")
            return
        draft['data']['dropoff'] = text
        draft['step'] = 'price_from'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['price_from'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    # Цена "от/до" и комиссия "от/до" - по прямой просьбе пользователя
    # (22.09.2026): "нужно везде сделать поле цена от и до, но необязательно
    # чтобы обе цены были указаны - достаточно одной цифры". Каждый шаг
    # принимает число или "-" (тот же skip-токен, что у шагов размеров груза
    # выше). Для цены (в отличие от комиссии) хотя бы одна граница
    # ОБЯЗАТЕЛЬНА - проверяется по завершении шага 'price_to'.
    if step == 'price_from':
        if text == '-':
            draft['data']['price_from'] = None
        else:
            digits = re.sub(r'[^\d]', '', text)
            if not digits:
                await message.answer("Не понял сумму - введи просто число, например 1500, или *-*, если не хочешь её указывать:", parse_mode='Markdown')
                return
            draft['data']['price_from'] = digits
        draft['step'] = 'price_to'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['price_to'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'price_to':
        if text == '-':
            draft['data']['price_to'] = None
        else:
            digits = re.sub(r'[^\d]', '', text)
            if not digits:
                await message.answer("Не понял сумму - введи просто число, например 2000, или *-*, если не хочешь её указывать:", parse_mode='Markdown')
                return
            draft['data']['price_to'] = digits
        if not draft['data'].get('price_from') and not draft['data'].get('price_to'):
            # Хотя бы одна граница цены обязательна - возвращаемся к первой.
            draft['step'] = 'price_from'
            state['order_draft'] = draft
            await message.answer("Нужно указать хотя бы одну цену - от или до. " + SHARED_ORDER_STEP_PROMPTS['price_from'], parse_mode='Markdown')
            return
        draft['step'] = 'commission_from'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['commission_from'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'commission_from':
        if text == '-':
            draft['data']['commission_from'] = None
        else:
            digits = re.sub(r'[^\d]', '', text)
            draft['data']['commission_from'] = digits or None
        draft['step'] = 'commission_to'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['commission_to'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'commission_to':
        if text == '-':
            draft['data']['commission_to'] = None
        else:
            digits = re.sub(r'[^\d]', '', text)
            draft['data']['commission_to'] = digits or None
        draft['step'] = 'car_class'
        state['order_draft'] = draft
        await message.answer("🚘 Выбери класс автомобиля 👇", reply_markup=shared_order_car_class_keyboard())
        return

    if step == 'car_class':
        if text not in SHARE_ORDER_CAR_CLASS_NAMES:
            await message.answer("Выбери класс кнопкой на клавиатуре 👇", reply_markup=shared_order_car_class_keyboard())
            return
        draft['data']['car_class'] = text
        if SHARE_ORDER_PASSENGERS_BY_CLASS.get(text):
            draft['step'] = 'passengers'
            state['order_draft'] = draft
            max_pax = SHARE_ORDER_MAX_PASSENGERS_BY_CLASS.get(text) or 5
            await message.answer(f"👥 Сколько пассажиров? (максимум {max_pax})", reply_markup=shared_order_passengers_keyboard(text))
        elif SHARE_ORDER_LOADER_CHOICE_BY_CLASS.get(text):
            # Пеший курьер/Курьер на авто/Грузовая машина - "Пассажиров" не
            # имеет смысла; "Нужен грузчик?" задаётся, но необязателен
            # (изменено 22.09.2026 по прямой просьбе пользователя - можно
            # пропустить, см. shared_order_yes_no_keyboard/step=='loader_needed').
            draft['data']['passengers'] = ''
            draft['step'] = 'loader_needed'
            state['order_draft'] = draft
            await message.answer(SHARED_ORDER_STEP_PROMPTS['loader_needed'], reply_markup=shared_order_yes_no_keyboard(), parse_mode='Markdown')
        else:
            draft['data']['passengers'] = ''
            draft['step'] = 'client_phone'
            state['order_draft'] = draft
            await message.answer(SHARED_ORDER_STEP_PROMPTS['client_phone'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'passengers':
        digits = re.sub(r'[^\d]', '', text)
        max_pax = SHARE_ORDER_MAX_PASSENGERS_BY_CLASS.get(draft['data'].get('car_class')) or 5
        if not digits or int(digits) <= 0 or int(digits) > max_pax:
            await message.answer(f"Введи число пассажиров от 1 до {max_pax} или выбери кнопкой 👇", reply_markup=shared_order_passengers_keyboard(draft['data'].get('car_class')))
            return
        draft['data']['passengers'] = digits
        draft['step'] = 'client_phone'
        state['order_draft'] = draft
        await message.answer(SHARED_ORDER_STEP_PROMPTS['client_phone'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    if step == 'loader_needed':
        if text not in ('Да', 'Нет', '➖ Не отвечать', '-'):
            await message.answer("Выбери кнопкой «Да»/«Нет», или «Не отвечать», если не хочешь указывать 👇", reply_markup=shared_order_yes_no_keyboard())
            return
        draft['data']['loader_needed'] = 'yes' if text == 'Да' else ('no' if text == 'Нет' else None)
        if SHARE_ORDER_CARGO_DIMS_BY_CLASS.get(draft['data'].get('car_class')):
            draft['step'] = 'cargo_length'
            state['order_draft'] = draft
            await message.answer(SHARED_ORDER_STEP_PROMPTS['cargo_length'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        else:
            draft['step'] = 'client_phone'
            state['order_draft'] = draft
            await message.answer(SHARED_ORDER_STEP_PROMPTS['client_phone'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
        return

    # Шаги размеров/объёма/веса груза - ТОЛЬКО для "Грузовая машина" (см.
    # SHARE_ORDER_CARGO_DIMS_BY_CLASS), необязательные (можно прислать "-").
    cargo_step_chain = [
        ('cargo_length', 'cargo_length_cm', 'cargo_width'),
        ('cargo_width', 'cargo_width_cm', 'cargo_height'),
        ('cargo_height', 'cargo_height_cm', 'cargo_volume'),
        ('cargo_volume', 'cargo_volume_m3', 'cargo_weight'),
        ('cargo_weight', 'cargo_weight_kg', 'client_phone'),
    ]
    for cur_step, field, next_step in cargo_step_chain:
        if step == cur_step:
            if text == '-':
                draft['data'][field] = None
            else:
                normalized = text.replace(',', '.')
                try:
                    draft['data'][field] = float(re.sub(r'[^\d.]', '', normalized)) if re.sub(r'[^\d.]', '', normalized) else None
                except ValueError:
                    draft['data'][field] = None
                if draft['data'][field] is None:
                    await message.answer("Не понял число - пришли просто цифры (например 120.5) или *-*, если неизвестно:", parse_mode='Markdown')
                    return
            draft['step'] = next_step
            state['order_draft'] = draft
            if next_step == 'client_phone':
                await message.answer(SHARED_ORDER_STEP_PROMPTS['client_phone'], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
            else:
                await message.answer(SHARED_ORDER_STEP_PROMPTS[next_step], reply_markup=shared_order_cancel_keyboard(), parse_mode='Markdown')
            return

    if step == 'client_phone':
        if not text:
            await message.answer("Пришли номер телефона клиента или *-*, если его нет:", parse_mode='Markdown')
            return
        draft['data']['client_phone'] = None if text == '-' else text
        draft['step'] = 'confirm'
        state['order_draft'] = draft
        await show_shared_order_confirmation(message, draft['data'], category, city)
        return

    # step == 'confirm' - здесь ждём нажатия инлайн-кнопок на сообщении выше,
    # а не текста; "❌ ОТМЕНА" обработана в самом начале функции.
    await message.answer("Нажми «📤 Отправить заказ» или «❌ Отменить» на сообщении выше 👆")

def format_shared_order_cargo_line(data):
    """Строка "📦 Груз: ..." для confirm/broadcast/accept-текстов (по прямой
    просьбе пользователя, 22.09.2026: размеры/объём/вес - ТОЛЬКО у
    "Грузовая машина") - показывается, только если хоть одно из полей задано;
    работает и со словарём черновика (order_draft['data']), и с
    dict-представлением строки БД (get_shared_order), т.к. ключи одинаковые."""
    if not any(data.get(k) for k in ('cargo_length_cm', 'cargo_width_cm', 'cargo_height_cm', 'cargo_volume_m3', 'cargo_weight_kg')):
        return ""
    dims = ''
    if data.get('cargo_length_cm') or data.get('cargo_width_cm') or data.get('cargo_height_cm'):
        dims = f"{data.get('cargo_length_cm') or '?'}×{data.get('cargo_width_cm') or '?'}×{data.get('cargo_height_cm') or '?'} см"
    parts = [p for p in [dims, f"{data['cargo_volume_m3']} м³" if data.get('cargo_volume_m3') else '',
                          f"{data['cargo_weight_kg']} кг" if data.get('cargo_weight_kg') else ''] if p]
    return f"📦 Груз: {', '.join(parts)}\n"

async def broadcast_shared_order(order_id, data, city, category, sender_id):
    """Рассылает объявление о заказе ВСЕМ водителям того же города (любой
    категории - по просьбе пользователя 22.09.2026, список классов авто
    больше не привязан к категории, см. SHARE_ORDER_CAR_CLASSES), кроме
    самого отправителя. Как и push_airport_status_change - берём СРЕЗ
    user_state (рассылка не мгновенная, список не должен "плыть" по ходу)."""
    if not bot:
        return 0
    recipients = [
        uid for uid, s in list(user_state.items())
        if isinstance(s, dict) and uid != sender_id and s.get('city') == city
    ]
    if not recipients:
        return 0

    passengers_line = f"👥 Пассажиров: {data['passengers']}\n" if data.get('passengers') else ""
    loader_line = f"🧑‍🔧 Нужен грузчик: {'Да' if data.get('loader_needed') == 'yes' else 'Нет'}\n" if data.get('loader_needed') else ""
    cargo_line = format_shared_order_cargo_line(data)
    price_line = format_share_order_price_range(data.get('price_from'), data.get('price_to'))
    commission_line = format_share_order_price_range(data.get('commission_from'), data.get('commission_to'), label='Комиссия', emoji='💼')
    text = (
        f"🔄 *Заказ от другого водителя* (#{order_id})\n\n"
        f"📍 Подача: {escape_md(data['pickup'])}\n"
        f"🏁 Прибытие: {escape_md(data['dropoff'])}\n"
        f"{price_line}"
        f"{commission_line}"
        f"🚘 Класс: {data['car_class']}\n"
        f"{passengers_line}"
        f"{loader_line}"
        f"{cargo_line}\n"
        f"_Предложение действует {SHARED_ORDER_EXPIRY_HOURS} час. Кто первый примет - получит контакт отправителя._"
    )
    keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="✅ ПРИНЯТЬ ЗАКАЗ", callback_data=f"order_accept_{order_id}")],
        [InlineKeyboardButton(text="❌ ОТКАЗАТЬСЯ", callback_data=f"order_decline_{order_id}")]
    ])
    sent = 0
    for uid in recipients:
        try:
            await bot.send_message(uid, text, reply_markup=keyboard, parse_mode='Markdown')
            sent += 1
        except Exception as e:
            logger.warning(f"⚠️ Не удалось отправить заказ #{order_id} водителю {uid}: {e}")
        await asyncio.sleep(0.05)  # Telegram допускает ~30 сообщений/сек в разные чаты - берём с запасом
    logger.info(f"🔄 Заказ #{order_id} разослан {sent}/{len(recipients)} водителям города {city}")
    return sent

@router.callback_query(lambda c: c.data == "order_confirm_cancel")
async def cancel_shared_order_draft(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    state = user_state.get(user_id, {})
    state.pop('order_draft', None)
    await callback_query.message.edit_text("Черновик заказа отменён.")
    await callback_query.answer()
    await callback_query.message.answer("Выбери действие 👇", reply_markup=services_keyboard(state.get('category'), state.get('city'), user_id))

@router.callback_query(lambda c: c.data == "order_confirm_send")
async def confirm_send_shared_order(callback_query: types.CallbackQuery):
    user_id = callback_query.from_user.id
    state = user_state.get(user_id)
    if not state or state.get('order_draft', {}).get('step') != 'confirm':
        await callback_query.answer("Черновик не найден - начни заново", show_alert=True)
        return
    data = state['order_draft']['data']
    category = state.get('category')
    city = state.get('city')
    city_name = CITY_DISPLAY_NAMES.get(city, city)

    sender_contact = format_user_contact(callback_query.from_user)
    order_id = create_shared_order(
        user_id, sender_contact, city, category, data['pickup'], data['dropoff'], data.get('price_from'),
        data.get('price_to'), data['car_class'], data['passengers'], data.get('client_phone'), data.get('loader_needed'),
        data.get('cargo_length_cm'), data.get('cargo_width_cm'), data.get('cargo_height_cm'),
        data.get('cargo_volume_m3'), data.get('cargo_weight_kg'),
        data.get('commission_from'), data.get('commission_to'),
    )
    state.pop('order_draft', None)

    await callback_query.message.edit_text(f"⏳ Отправляю заказ #{order_id} водителям города {city_name}...")
    await callback_query.answer()

    sent = await broadcast_shared_order(order_id, data, city, category, user_id)
    if sent > 0:
        await callback_query.message.edit_text(f"✅ Заказ #{order_id} отправлен {sent} водителям города {city_name}. Ждём отклика - предложение действует {SHARED_ORDER_EXPIRY_HOURS} час.")
    else:
        await callback_query.message.edit_text(
            f"✅ Заказ #{order_id} создан, но сейчас в городе {city_name} нет других известных водителей. "
            f"Как только кто-то из них напишет боту, увидит твой заказ, пока он не истёк."
        )
    await callback_query.message.answer("Выбери действие 👇", reply_markup=services_keyboard(category, city, user_id))

@router.callback_query(lambda c: c.data.startswith('order_accept_'))
async def accept_shared_order(callback_query: types.CallbackQuery):
    order_id = int(callback_query.data[len('order_accept_'):])
    order = get_shared_order(order_id)
    if not order:
        await callback_query.answer("Заказ не найден", show_alert=True)
        return
    if order['status'] != 'open' or is_shared_order_expired(order):
        if order['status'] == 'open':
            expire_shared_order(order_id)
        await callback_query.message.edit_text("😔 Этот заказ уже занят другим водителем или срок предложения истёк.")
        await callback_query.answer("Заказ уже недоступен", show_alert=True)
        return

    accepted_by_contact = format_user_contact(callback_query.from_user)
    won = try_accept_shared_order(order_id, callback_query.from_user.id, accepted_by_contact)
    if not won:
        # Кто-то другой принял на долю секунды раньше - атомарный UPDATE (см.
        # try_accept_shared_order) сам разрулил гонку, здесь просто сообщаем.
        await callback_query.message.edit_text("😔 Этот заказ уже занят другим водителем - вы опоздали буквально на секунды.")
        await callback_query.answer("Заказ уже занят", show_alert=True)
        return

    text = (
        f"✅ *Вы приняли заказ #{order_id}*\n\n"
        f"📍 Подача: {escape_md(order['pickup'])}\n"
        f"🏁 Прибытие: {escape_md(order['dropoff'])}\n"
        f"{format_share_order_price_range(order.get('price_from'), order.get('price_to'))}"
        f"{format_share_order_price_range(order.get('commission_from'), order.get('commission_to'), label='Комиссия', emoji='💼')}"
        f"🚘 Класс: {order['car_class']}\n"
    )
    if order.get('passengers'):
        text += f"👥 Пассажиров: {order['passengers']}\n"
    if order.get('loader_needed'):
        text += f"🧑‍🔧 Нужен грузчик: {'Да' if order['loader_needed'] == 'yes' else 'Нет'}\n"
    text += format_shared_order_cargo_line(order)
    if order.get('client_phone'):
        # Телефон клиента - не в общей рассылке (см. broadcast_shared_order),
        # виден только тому, кто реально принял заказ.
        text += f"📱 Телефон клиента: {escape_md(order['client_phone'])}\n"
    text += f"\n📞 Свяжитесь с отправителем: {order['sender_contact']}"
    # "✅ ЗАКАЗ ВЫПОЛНЕН" - по прямой просьбе пользователя (22.09.2026),
    # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "засчитывается
    # только у того, кто заказ принял и выполняет, тот кто его дал - он
    # ему не нужен"): кнопка теперь ТОЛЬКО у принявшего (accepted_by) -
    # отправителю она не показывается, счётчик засчитывается одним
    # нажатием, без ожидания подтверждения второй стороны (см.
    # order_done_{order_id} ниже).
    done_keyboard = InlineKeyboardMarkup(inline_keyboard=[
        [InlineKeyboardButton(text="✅ ЗАКАЗ ВЫПОЛНЕН", callback_data=f"order_done_{order_id}")]
    ])
    await callback_query.message.edit_text(text, reply_markup=done_keyboard, parse_mode='Markdown')
    await callback_query.answer("Заказ принят!")

    if bot:
        try:
            await bot.send_message(
                order['sender_id'],
                f"🎉 *Ваш заказ #{order_id} принят!*\n\n📞 Свяжитесь с водителем: {accepted_by_contact}",
                parse_mode='Markdown'
            )
        except Exception as e:
            logger.warning(f"⚠️ Не удалось уведомить отправителя {order['sender_id']} о принятии заказа #{order_id}: {e}")

@router.callback_query(lambda c: c.data.startswith('order_decline_'))
async def decline_shared_order(callback_query: types.CallbackQuery):
    await callback_query.message.edit_text("Вы отказались от этого заказа.")
    await callback_query.answer()

@router.callback_query(lambda c: c.data.startswith('order_done_'))
async def order_done_callback(callback_query: types.CallbackQuery):
    """"✅ ЗАКАЗ ВЫПОЛНЕН" - по прямой просьбе пользователя (22.09.2026).
    ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "засчитывается только
    у того, кто заказ принял и выполняет, тот кто его дал - он ему не
    нужен"): раньше требовалось взаимное подтверждение (и отправитель, и
    принявший), теперь кнопка есть ТОЛЬКО у принявшего (accepted_by, см.
    accept_shared_order) и счётчик засчитывается ОДНИМ нажатием, без
    ожидания второй стороны. accepter_confirmed_at всё равно используется -
    как флаг "уже засчитано", чтобы повторное нажатие не удваивало счётчик."""
    order_id = int(callback_query.data[len('order_done_'):])
    order = get_shared_order(order_id)
    if not order or not order.get('accepted_by'):
        await callback_query.answer("Заказ не найден", show_alert=True)
        return
    if callback_query.from_user.id != order['accepted_by']:
        await callback_query.answer("Это не ваш заказ", show_alert=True)
        return

    order_after, just_completed = confirm_shared_order_done(order_id, is_sender=False)

    if just_completed:
        await callback_query.message.edit_text(f"✅ Заказ #{order_id} засчитан как выполненный!")
    else:
        # accepter_confirmed_at уже был проставлен раньше (повторное
        # нажатие) - счётчик не трогаем повторно.
        await callback_query.message.edit_text(f"✅ Заказ #{order_id} уже был отмечен как выполненный.")
    await callback_query.answer("Отмечено!")

    if just_completed and bot:
        # Отправителю больше НЕ шлём отдельное уведомление (22.09.2026 -
        # ему эта механика "не нужна", см. docstring выше) - счётчик и
        # сообщение только у принявшего.
        new_count = increment_completed_orders(order['accepted_by'])
        count_text = f" Выполненных заказов: {new_count}" if new_count is not None else ""
        try:
            await bot.send_message(order['accepted_by'], f"🎉 Заказ засчитан!{count_text}")
        except Exception as e:
            logger.warning(f"⚠️ Не удалось уведомить принявшего {order['accepted_by']} о засчитанном заказе #{order_id}: {e}")

# ==================== МОДУЛЬ "ИНСТРУМЕНТЫ ВОДИТЕЛЯ" - хендлеры ====================

@router.message(lambda message: message.text == "🧰 ИНСТРУМЕНТЫ ВОДИТЕЛЯ")
async def open_courier_module(message: types.Message):
    user_id = message.from_user.id
    state = user_state.get(user_id)
    if not state or 'category' not in state:
        await message.answer("Сначала выбери город и категорию!")
        return
    if state.get('category') not in COURIER_MODULE_CATEGORIES:
        # COURIER_MODULE_CATEGORIES сейчас = все категории, но проверку
        # оставляем на случай, если позже какую-то категорию снова исключат.
        await message.answer(
            "Этот раздел пока недоступен для твоей категории.",
            reply_markup=services_keyboard(state.get('category'), state.get('city'), user_id),
        )
        return
    # ИЗМЕНЕНО 22.09.2026 (прямая жалоба пользователя - "у нас больше нет
    # инструменты водителя, откуда это меню, у нас же сейчас миниапп") - этот
    # хендлер срабатывает ТОЛЬКО если у кого-то в Telegram-клиенте с ДО
    # миграции на "👤 Личный кабинет" (21.09.2026) всё ещё физически лежит
    # старая reply-клавиатура с кнопкой "🧰 ИНСТРУМЕНТЫ ВОДИТЕЛЯ" (сам бот эту
    # кнопку уже нигде не отправляет - см. комментарий у 4721 строки). Раньше
    # здесь заново открывался весь старый модуль (courier_module_keyboard) -
    # так стухшая клавиатура пересоздавала сама себя до бесконечности. Теперь
    # вместо этого явно отправляем в актуальный интерфейс и СТИРАЕМ старую
    # клавиатуру (ReplyKeyboardRemove), чтобы больше никогда не всплывала.
    state.pop('in_courier_module', None)
    await message.answer(
        "🧰 Этот раздел переехал в «👤 Личный кабинет» - открой его кнопкой снизу.",
        reply_markup=types.ReplyKeyboardRemove(),
    )

@router.message(lambda message: message.text == "💰 ФИНАНСЫ" and user_state.get(message.from_user.id, {}).get('in_courier_module'))
async def start_courier_finance(message: types.Message):
    user_id = message.from_user.id
    state = user_state[user_id]
    state['courier_finance_draft'] = {'step': 'income', 'data': {}}
    await message.answer(COURIER_FINANCE_STEP_PROMPTS['income'], reply_markup=courier_finance_cancel_keyboard())
    # "📈 СТАТИСТИКА СМЕН" - по просьбе пользователя (20.09.2026) доступна
    # прямо отсюда, отдельной инлайн-кнопкой под первым шагом расчёта (см.
    # show_shift_stats) - не отдельный пункт меню, чтобы не плодить кнопки в
    # courier_module_keyboard. "👤 ЛИЧНЫЙ КАБИНЕТ" (21.09.2026) - та же
    # статистика, но графиками в WebApp (см. CABINET_WEBAPP_PATH) вместо
    # текстового списка по дням; показывается только если PUBLIC_URL задан
    # (тот же guard, что у "🗺 КАРТА ВОДИТЕЛЕЙ" в services_keyboard - Telegram
    # требует HTTPS для WebApp).
    stats_row = [InlineKeyboardButton(text="📈 СТАТИСТИКА СМЕН", callback_data="show_shift_stats")]
    if PUBLIC_URL:
        # tariffs= - варианты тарифа для выпадающего списка в анкете личного
        # кабинета (см. cabinet_webapp_html) - берутся из CATEGORIES текущей
        # категории водителя, тот же приём, что city/category у карты.
        tariff_options = CATEGORIES.get(state.get('category'), {}).get('tariffs', [])
        cabinet_url = f"{PUBLIC_URL}{CABINET_WEBAPP_PATH}?tariffs={urllib.parse.quote(','.join(tariff_options))}"
        stats_row.append(InlineKeyboardButton(text="👤 ЛИЧНЫЙ КАБИНЕТ", web_app=WebAppInfo(url=cabinet_url)))
    await message.answer(
        "Или посмотри статистику своих смен за последние 6 месяцев:",
        reply_markup=InlineKeyboardMarkup(inline_keyboard=[stats_row]),
    )

