async def handle_cabinet_data_api(request):
    """JSON API личного кабинета - в отличие от /map/positions initData
    здесь ОБЯЗАТЕЛЕН (см. комментарий у CABINET_WEBAPP_PATH выше): без
    валидной подписи user_id неизвестен и непроверяем, поэтому отдавать
    что-либо просто некому/нельзя - 401."""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    parsed = validate_telegram_webapp_init_data(init_data, BOT_TOKEN) if BOT_TOKEN else None
    if not parsed:
        # Временное диагностическое логирование (21.09.2026) - пользователь
        # видит "Не удалось загрузить данные" в реальном кабинете, а эта
        # ветка (401) раньше молча ничего не писала в лог, поэтому причину
        # было не видно в Railway logs. Не логируем сам init_data целиком
        # (в нём подпись/telegram user payload) - только длину и факт
        # наличия BOT_TOKEN.
        logger.warning(
            f"⚠️ /cabinet/data: невалидный initData (len={len(init_data)}, "
            f"bot_token_set={bool(BOT_TOKEN)}) - отдаю 401"
        )
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        tg_user = json.loads(parsed.get('user', '{}'))
        user_id = tg_user.get('id')
    except Exception:
        user_id = None
    if not user_id:
        logger.warning("⚠️ /cabinet/data: initData валиден, но не удалось извлечь user_id - отдаю 401")
        return web.json_response({'error': 'invalid_init_data'}, status=401)

    try:
        shift_rows = get_shift_history(user_id)  # [(shift_date, duration_minutes, km, airport_wait_minutes), ...]
        finance_rows = get_finance_history(user_id)  # [(calc_date, income, net_profit), ...]

        shifts_by_day = {}
        for shift_date, duration_minutes, km, _airport_wait_minutes in shift_rows:
            agg = shifts_by_day.setdefault(shift_date, {'minutes': 0, 'km': 0.0})
            agg['minutes'] += duration_minutes
            agg['km'] += km

        # Несколько расчётов "ДЕНЬ - ИТОГ" за один день - берём сумму (по
        # аналогии со сменами выше), это ближе к реальности, чем "только
        # последний" (человек мог посчитать доход дважды за смену).
        finance_by_day = {}
        for calc_date, income, net_profit, trips_count in finance_rows:
            agg = finance_by_day.setdefault(calc_date, {'income': 0.0, 'net_profit': 0.0, 'trips_count': 0})
            agg['income'] += income
            agg['net_profit'] += net_profit
            agg['trips_count'] += trips_count or 0

        today = datetime.now(timezone.utc).date()
        today_str = today.isoformat()
        week_cutoff = (today - timedelta(days=7)).isoformat()
        month_cutoff = (today - timedelta(days=30)).isoformat()

        def sum_shifts(cutoff):
            minutes = sum(a['minutes'] for d, a in shifts_by_day.items() if d >= cutoff)
            km = sum(a['km'] for d, a in shifts_by_day.items() if d >= cutoff)
            return minutes, km

        def sum_finance(cutoff):
            net = sum(a['net_profit'] for d, a in finance_by_day.items() if d >= cutoff)
            return net

        # "За сегодня" (по просьбе пользователя, 21.09.2026) - тот же принцип
        # sum_shifts/sum_finance с cutoff=today_str, отдельно от недели/месяца.
        today_minutes, today_km = sum_shifts(today_str)
        today_net_profit = sum_finance(today_str)
        week_minutes, week_km = sum_shifts(week_cutoff)
        month_minutes, month_km = sum_shifts(month_cutoff)
        total_minutes = sum(a['minutes'] for a in shifts_by_day.values())
        total_km = sum(a['km'] for a in shifts_by_day.values())
        period_net_profit = sum(a['net_profit'] for a in finance_by_day.values())
        avg_per_hour = (period_net_profit / (total_minutes / 60)) if total_minutes else 0

        # "Лучший день" за весь период по чистыми - для карточки-акцента в
        # кабинете (по просьбе пользователя, "крутая визуализация"), не
        # только сухие суммы.
        best_day = None
        if finance_by_day:
            best_date = max(finance_by_day, key=lambda d: finance_by_day[d]['net_profit'])
            if finance_by_day[best_date]['net_profit'] > 0:
                best_day = {'date': best_date, 'net_profit': round(finance_by_day[best_date]['net_profit'])}

        # Графики - последние 30 дней, по возрастанию даты (слева направо на
        # графике = раньше -> позже), включая дни без данных (нули), чтобы
        # ось X была ровной шкалой дат, а не "прыгала" только по дням с
        # активностью.
        days_axis = [(today - timedelta(days=i)).isoformat() for i in range(29, -1, -1)]
        earnings_series = [round(finance_by_day.get(d, {}).get('net_profit', 0.0)) for d in days_axis]
        hours_series = [round(shifts_by_day.get(d, {}).get('minutes', 0) / 60, 1) for d in days_axis]

        result = {
            'profile': get_driver_profile(user_id) or {'full_name': '', 'tariff': '', 'car_model': '', 'car_plate': '', 'completed_orders_count': 0},
            'totals': {
                'today_hours': round(today_minutes / 60, 1), 'today_km': round(today_km),
                'today_net_profit': round(today_net_profit),
                'week_hours': round(week_minutes / 60, 1), 'week_km': round(week_km),
                'month_hours': round(month_minutes / 60, 1), 'month_km': round(month_km),
                'period_hours': round(total_minutes / 60, 1), 'period_km': round(total_km),
                'period_months': SHIFT_HISTORY_MONTHS,
                'week_net_profit': round(sum_finance(week_cutoff)),
                'month_net_profit': round(sum_finance(month_cutoff)),
                'period_net_profit': round(period_net_profit),
                'avg_per_hour': round(avg_per_hour),
                'best_day': best_day,
            },
            'chart': {'days': days_axis, 'earnings': earnings_series, 'hours': hours_series},
            # Данные сегодняшних завершённых смен - используются в WebApp,
            # чтобы автоматически подставить км/часы в форму "Финансы" (по
            # аналогии с Telegram-версией, см. today_shift_totals/
            # advance_finance_step, 21.09.2026).
            'today_shift': (lambda st: {
                'km': round(st['km'], 1), 'hours': round(st['minutes'] / 60, 2),
                'airport_wait_minutes': st['airport_wait_minutes'],
            })(today_shift_totals(user_id)),
            # ДОБАВЛЕНО 22.09.2026 (см. save_last_day_summary) - последний
            # посчитанный "ДЕНЬ - ИТОГ" (из Telegram-диалога ИЛИ из формы
            # Кабинета - неважно, откуда), если он сегодняшний. Вчерашний
            # (или более старый) не отдаём - вкладка "Профиль" не должна
            # показывать устаревший итог как будто это данные за сегодня.
            'day_summary': (lambda ds: ds if (ds and ds.get('date') == datetime.now(ZoneInfo('Europe/Moscow')).date().isoformat()) else None)(
                (user_state.get(user_id) or {}).get('last_day_summary')
            ),
        }
    except Exception:
        logger.exception(f"❌ Ошибка при сборе данных личного кабинета user_id={user_id}")
        return web.json_response({'error': 'internal_error'}, status=500)
    return web.json_response(result)

CABINET_PROFILE_API_PATH = '/cabinet/profile'
CABINET_PROFILE_FIELD_MAX_LEN = 60  # разумный предел на длину каждого поля анкеты - защита от мусора/абьюза поля

async def handle_cabinet_profile_api(request):
    """Сохраняет анкету водителя (ник/ФИО, тариф, машина, номер) из личного
    кабинета - POST с телом {full_name, tariff, car_model, car_plate}. Та же
    строгая проверка initData, что и у /cabinet/data (см. комментарий у
    CABINET_WEBAPP_PATH) - это запись чужих персональных данных, без
    валидной подписи запрос просто отклоняется."""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    parsed = validate_telegram_webapp_init_data(init_data, BOT_TOKEN) if BOT_TOKEN else None
    if not parsed:
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        tg_user = json.loads(parsed.get('user', '{}'))
        user_id = tg_user.get('id')
    except Exception:
        user_id = None
    if not user_id:
        return web.json_response({'error': 'invalid_init_data'}, status=401)

    try:
        body = await request.json()
    except Exception:
        return web.json_response({'error': 'invalid_body'}, status=400)

    def clean(value):
        return str(value or '').strip()[:CABINET_PROFILE_FIELD_MAX_LEN]

    full_name = clean(body.get('full_name'))
    tariff = clean(body.get('tariff'))
    car_model = clean(body.get('car_model'))
    car_plate = clean(body.get('car_plate'))

    ok = save_driver_profile(user_id, full_name, tariff, car_model, car_plate)
    if not ok:
        return web.json_response({'error': 'save_failed'}, status=500)
    return web.json_response({'ok': True})

# ==================== ЛИЧНЫЙ КАБИНЕТ - РАСШИРЕНИЕ (21.09.2026) ====================
# По прямой просьбе пользователя: "надо обьеденить кнопки инструменты
# водителя и настройки сделать одну кнопку Личный кабинет и в нем сделать
# приложение где будут все функции этих кнопок" (и явно выбранный пользователем
# вариант "всё в приложение, включая геолокацию", когда уточняли объём) -
# ниже 5 новых HTTP-эндпоинтов, все на том же /cabinet WebApp, каждый - тонкая
# обёртка над УЖЕ существующей функцией/хендлером Telegram-версии (никакая
# логика не дублируется и не переписывается заново в JS): Финансы ->
# calculate_finance_result+save_finance_result (те же, что
# send_courier_finance_result), Спрос сейчас/Часы пика -> те же тексты/ссылки,
# что show_kef_bot/format_peak_hours_text, Рядом (гео) -> тот же
# nearest_nearby_points/yandex_navi_url, что handle_nearby_location, Настройки
# -> те же notif_prefs/enable_airport_queue_tracking, что
# toggle_notification_setting/toggle_airport_queue_inline. Везде - строгая
# проверка initData (401 без валидной подписи), как и у /cabinet/data выше -
# это персональные данные/действия конкретного человека.
def _cabinet_require_user(request):
    """Общая проверка initData для всех новых /cabinet/* эндпоинтов ниже -
    возвращает user_id или None (вызывающий код тогда отвечает 401).
    Временное диагностическое логирование (21.09.2026, см. такое же у
    /cabinet/data выше) - причина 401 раньше нигде не логировалась."""
    init_data = request.headers.get('X-Telegram-Init-Data', '')
    parsed = validate_telegram_webapp_init_data(init_data, BOT_TOKEN) if BOT_TOKEN else None
    if not parsed:
        logger.warning(
            f"⚠️ {request.path}: невалидный initData (len={len(init_data)}, "
            f"bot_token_set={bool(BOT_TOKEN)}) - отдаю 401"
        )
        return None
    try:
        tg_user = json.loads(parsed.get('user', '{}'))
        return tg_user.get('id')
    except Exception:
        logger.warning(f"⚠️ {request.path}: initData валиден, но не удалось извлечь user_id - отдаю 401")
        return None

CABINET_FINANCE_API_PATH = '/cabinet/finance'
# ДОБАВЛЕНО 22.09.2026 (прямая жалоба пользователя - "запоминай один раз
# ввёл, чтобы не вводить каждый раз налог/своя машина/расход/цена топлива" +
# уточнение "все эти данные можно вбить по новой в кабинете") - раньше
# запоминание "запоминаемых" полей (FINANCE_REMEMBERED_FIELDS/
# finance_defaults) работало ТОЛЬКО в пошаговом Telegram-расчёте
# (advance_finance_step/remember_finance_default) - в Кабинете (WebApp,
# одна форма сразу) те же поля надо было вбивать заново при каждом расчёте,
# ничего не запоминалось и не подставлялось. Теперь используем тот же
# state['finance_defaults'], что и Telegram-версия (единый профиль для
# обоих интерфейсов): GET отдаёт сохранённые значения для подстановки в
# форму при открытии вкладки, POST после расчёта сохраняет введённые
# значения как новые дефолты (поля остаются обычными <input> - водитель в
# любой момент может ввести другое число поверх подставленного, оно тут же
# станет новым запомненным значением).
CABINET_FINANCE_DEFAULTS_API_PATH = '/cabinet/finance/defaults'

async def handle_cabinet_finance_defaults_api(request):
    """GET -> {consumption, fuel_price, rent, tax_rate, car_ownership}
    (любое поле может отсутствовать, если ещё ни разу не вводилось) - для
    подстановки в форму "Финансы" при открытии вкладки Кабинета."""
    user_id = _cabinet_require_user(request)
    if not user_id:
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    state = user_state.get(user_id) or {}
    defaults = finance_defaults(state)
    return web.json_response({
        'consumption': defaults.get('consumption'),
        'fuel_price': defaults.get('fuel_price'),
        'rent': defaults.get('rent'),
        'tax_rate': defaults.get('tax_rate'),
        'car_ownership': defaults.get('car_ownership'),
    })

async def handle_cabinet_finance_api(request):
    """POST {income, km, consumption, fuel_price, car_ownership, rent,
    expenses, tax_rate, hours} -> тот же расчёт, что и в Telegram-версии
    (calculate_finance_result), результат сохраняется в ту же статистику
    (save_finance_result, см. get_finance_history/handle_cabinet_data_api
    выше - значит появится и на графике "Заработок по дням"). Заодно
    запоминает "повторяющиеся" поля в тот же profile, что и Telegram-версия
    (см. handle_cabinet_finance_defaults_api выше)."""
    user_id = _cabinet_require_user(request)
    if not user_id:
        return web.json_response({'error': 'invalid_init_data'}, status=401)
    try:
        body = await request.json()
        data = {
            'income': float(body['income']),
            'trips_count': int(body['trips_count']) if body.get('trips_count') else None,
            'km': float(body['km']),
            'consumption': float(body['consumption']),
            'fuel_price': float(body['fuel_price']),
            'car_ownership': body.get('car_ownership') or CAR_OWNERSHIP_OWN,
            'rent': float(body.get('rent') or 0),
            'expenses': float(body.get('expenses') or 0),
            'tax_rate': float(body.get('tax_rate') or DEFAULT_TAX_RATE_PERCENT),
            'hours': float(body['hours']),
        }
        if data['hours'] <= 0:
            return web.json_response({'error': 'invalid_hours'}, status=400)
    except Exception:
        return web.json_response({'error': 'invalid_body'}, status=400)

    r = calculate_finance_result(data)
    save_finance_result(user_id, r['income'], r['net_profit'], r['trips_count'])
    save_last_day_summary(user_id, r)

    state = user_state[user_id]
    remember_finance_default(state, 'consumption', data['consumption'])
    remember_finance_default(state, 'fuel_price', data['fuel_price'])
    remember_finance_default(state, 'tax_rate', data['tax_rate'])
    remember_finance_default(state, 'car_ownership', data['car_ownership'])
    # Аренду запоминаем только если машина реально в аренде - иначе "0"
    # затёр бы ранее сохранённую сумму аренды на случай, если водитель
    # временно посчитал день на своей машине.
    if data['car_ownership'] == CAR_OWNERSHIP_RENTED:
        remember_finance_default(state, 'rent', data['rent'])

    return web.json_response({
        'income': round(r['income']), 'fuel_cost': round(r['fuel_cost']),
        'wear_reserve': round(r['wear_reserve']), 'rent': round(r['rent']),
        'expenses': round(r['expenses']), 'tax_amount': round(r['tax_amount']),
        'tax_rate': r['tax_rate'], 'net_profit': round(r['net_profit']),
        'per_hour': round(r['per_hour']), 'is_rented': r['is_rented'],
        'trips_count': r['trips_count'], 'avg_check': round(r['avg_check']) if r['avg_check'] else None,
        'hours': r['hours'], 'km': r['km'],
    })

CABINET_DEMAND_API_PATH = '/cabinet/demand'

