async def check_subscription_expirations():
    """Проактивно уведомляет пользователей, у которых истёк триал/оплата, но
    которые с этого момента ещё не заходили в бота (иначе они и так упрутся
    в SubscriptionMiddleware при следующем обращении) - раз в
    SUBSCRIPTION_CHECK_INTERVAL_MINUTES минут."""
    # ИЗМЕНЕНО 22.09.2026 (см. subscription_state/get_subscription_group
    # выше) - источник теперь subscription_state (по группе), а не старая
    # subscriptions. Проверяем и шлём ТОЛЬКО если истекла группа, в которой
    # пользователь СЕЙЧАС (get_user_subscription_group) - если он в этот
    # момент работает в другой группе, у которой доступ ещё есть, пуш о
    # "своей" (неактуальной прямо сейчас) группе только сбивал бы с толку.
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT user_id, sub_group FROM subscription_state WHERE expired_notified = 0')
    rows = cursor.fetchall()
    conn.close()
    now = _sub_now()
    for user_id, sub_group in rows:
        if get_user_subscription_group(user_id) != sub_group:
            continue
        active_until = subscription_active_until(user_id, sub_group)
        if active_until is None or now < active_until:
            continue
        pay_url = await create_tinkoff_payment(user_id)
        text = subscription_paywall_text(user_id)
        if not pay_url:
            text += "\n\n⚠️ Не получилось создать ссылку на оплату, попробуй ещё раз чуть позже."
        try:
            if bot:
                await bot.send_message(user_id, text, reply_markup=subscription_paywall_keyboard(pay_url, user_id), parse_mode='Markdown')
        except Exception:
            logger.warning(f"⚠️ Не удалось отправить пуш об окончании подписки user_id={user_id}")
        conn2 = get_db_connection()
        cursor2 = conn2.cursor()
        cursor2.execute('UPDATE subscription_state SET expired_notified = 1 WHERE user_id = ? AND sub_group = ?', (user_id, sub_group))
        conn2.commit()
        conn2.close()
        await asyncio.sleep(0.05)


async def subscription_expiry_checker():
    while True:
        try:
            await check_subscription_expirations()
        except Exception:
            logger.exception("❌ Ошибка в subscription_expiry_checker")
        await asyncio.sleep(SUBSCRIPTION_CHECK_INTERVAL_MINUTES * 60)


# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "подготовь так же пуши
# 3 2 1 день 1 час и 10 мин до окончания подписки чтобы приходили с кнопкой
# оплатить подписку") - в отличие от check_subscription_expirations выше
# (которая шлёт ПОСЛЕ того, как доступ уже пропал), эти пуши ЗАРАНЕЕ
# предупреждают о скором окончании - и триала, и оплаченного периода (те же
# active_until/subscription_active_until, что и во всём остальном боте), с
# кнопкой "ОПЛАТИТЬ ПОДПИСКУ" прямо в сообщении. Отдельная, более частая
# проверка (SUBSCRIPTION_REMINDER_CHECK_INTERVAL_MINUTES=5, а не 60, как у
# check_subscription_expirations) - иначе порог "за 10 минут" мог бы вообще
# не попасть в проверяемое окно.
SUBSCRIPTION_REMINDER_CHECK_INTERVAL_MINUTES = 5

# Отсортированы от САМОГО БЛИЗКОГО срока к самому дальнему - см. порядок
# обхода в check_subscription_expiry_reminders (в рамках одного прогона
# отправляем САМОЕ срочное непосланное напоминание, а более дальние, которые
# тоже уже "проехали" - например, если бот был выключен несколько часов -
# просто отмечаем отправленными задним числом, отдельным сообщением не шлём).
SUBSCRIPTION_REMINDER_THRESHOLDS = [
    ('10m', timedelta(minutes=10), "🚨 *Подписка закончится через 10 минут!*\n\nПродли, чтобы не потерять доступ к боту."),
    ('1h', timedelta(hours=1), "⏰ *Подписка закончится через 1 час.*\n\nПродли, чтобы не потерять доступ к боту."),
    ('1d', timedelta(days=1), "⏳ *Подписка закончится через 1 день.*\n\nПродли заранее, чтобы не остаться без бота."),
    ('2d', timedelta(days=2), "⏳ *Подписка закончится через 2 дня.*\n\nПродли заранее, чтобы не остаться без бота."),
    ('3d', timedelta(days=3), "⏳ *Подписка закончится через 3 дня.*\n\nПродли заранее, чтобы не остаться без бота."),
]

def subscription_reminder_keyboard():
    return InlineKeyboardMarkup(inline_keyboard=[[
        InlineKeyboardButton(text="💳 ОПЛАТИТЬ ПОДПИСКУ", callback_data="sub_reminder_pay"),
    ]])

@router.callback_query(lambda c: c.data == "sub_reminder_pay")
async def sub_reminder_pay(callback_query: types.CallbackQuery):
    """Кнопка "ОПЛАТИТЬ ПОДПИСКУ" на пуше-напоминании (см.
    SUBSCRIPTION_REMINDER_THRESHOLDS выше) - ведёт в тот же экран оплаты, что
    и обычная кнопка меню (send_subscription_paywall сама запросит email,
    если он ещё не собран, и сама создаст ссылку Tinkoff)."""
    try:
        await callback_query.answer()
    except Exception:
        pass
    await send_subscription_paywall(callback_query)

async def check_subscription_expiry_reminders():
    # ИЗМЕНЕНО 22.09.2026 (см. subscription_state/get_subscription_group
    # выше) - источник теперь subscription_state (по группе), и напоминание
    # шлём только про ТЕКУЩУЮ группу пользователя (get_user_subscription_
    # group) - так же, как в check_subscription_expirations.
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT DISTINCT user_id, sub_group FROM subscription_state')
    rows = cursor.fetchall()
    conn.close()
    now = _sub_now()
    for user_id, sub_group in rows:
        if get_user_subscription_group(user_id) != sub_group:
            continue
        active_until = subscription_active_until(user_id, sub_group)
        if active_until is None or now >= active_until:
            continue  # уже истекло - это зона check_subscription_expirations, не дублируем
        time_left = active_until - now
        conn2 = get_db_connection()
        cursor2 = conn2.cursor()
        cursor2.execute('SELECT threshold FROM subscription_expiry_reminders WHERE user_id = ? AND sub_group = ?', (user_id, sub_group))
        sent_thresholds = {row[0] for row in cursor2.fetchall()}
        conn2.close()
        send_idx = None
        for idx, (key, threshold, text) in enumerate(SUBSCRIPTION_REMINDER_THRESHOLDS):
            if time_left <= threshold and key not in sent_thresholds:
                send_idx = idx
                break
        if send_idx is None:
            continue
        key, threshold, text = SUBSCRIPTION_REMINDER_THRESHOLDS[send_idx]
        try:
            if bot:
                await bot.send_message(user_id, text, reply_markup=subscription_reminder_keyboard(), parse_mode='Markdown')
        except Exception:
            logger.warning(f"⚠️ Не удалось отправить напоминание ({key}) об окончании подписки user_id={user_id}")
        # Отмечаем отправленным ЭТОТ порог и все более дальние (они по списку
        # идут следом, т.к. отсортированы от ближнего к дальнему) - раз более
        # срочный порог уже наступил, дальние тоже фактически "проехали" и
        # отдельного сообщения для них слать не нужно.
        try:
            conn3 = get_db_connection()
            conn3.executemany(
                'INSERT OR IGNORE INTO subscription_expiry_reminders (user_id, threshold, sub_group) VALUES (?, ?, ?)',
                [(user_id, k, sub_group) for k, _, _ in SUBSCRIPTION_REMINDER_THRESHOLDS[send_idx:]]
            )
            conn3.commit()
            conn3.close()
        except Exception:
            logger.exception(f"❌ Не удалось сохранить отметку о напоминании ({key}) для user_id={user_id}")
        await asyncio.sleep(0.05)

async def subscription_expiry_reminder_checker():
    while True:
        try:
            await check_subscription_expiry_reminders()
        except Exception:
            logger.exception("❌ Ошибка в subscription_expiry_reminder_checker")
        await asyncio.sleep(SUBSCRIPTION_REMINDER_CHECK_INTERVAL_MINUTES * 60)

# ==================== РЕФЕРАЛЬНАЯ ПРОГРАММА ====================
# По просьбе пользователя (20.09.2026): кнопка "Реферальная программа" в
# главном меню, 2 уровня начислений - 40% с каждого ЕЖЕМЕСЯЧНОГО платежа
# приглашённого напрямую (1 уровень), 20% с каждого платежа рефералов этого
# реферала (2 уровень, "реферал реферала"). Без ограничения на число
# рефералов. Вывод - только на карту, комиссия сервиса 3%, реальная выплата
# делается АДМИНОМ ВРУЧНУЮ (бот принимает заявку и уведомляет админа - у
# бота нет собственного API для переводов на карту; ADMIN_TELEGRAM_ID -
# id админа в Telegram, задаётся переменной окружения; выплата отмечается
# командой /referral_paid <id заявки>). Минимальная сумма вывода и проценты
# - разумные дефолты (пользователь просил "потом посмотрим как выглядит"),
# легко поменять константы ниже.
#
# REFERRAL_PROGRAM_LIVE = False (по прямой просьбе пользователя, 20.09.2026:
# "загрузим на деплой, но везде заглушки") - кнопка "🤝 Реферальная
# программа" в меню ЕСТЬ и задеплоена, но при нажатии показывает заглушку
# "скоро заработает" вместо реальной статистики/ссылки/вывода - см.
# show_referral_program ниже. Вся логика начислений (distribute_referral_
# earnings) при этом не срабатывает сама по себе - для неё в принципе нужны
# подтверждённые платежи подписки, которых пока не бывает, пока
# SUBSCRIPTION_ENFORCEMENT_LIVE = False. Включать оба флага - отдельное
# решение пользователя, когда Tinkoff будет настроен.
#
# ВКЛЮЧЕНО 23.09.2026 (прямая просьба пользователя - "сразу выведи две
# кнопки с реферальной программой для двух категорий под кнопкой
# реферальная программа и запароль юрлиц введи пароль 261194"): теперь при
