def ensure_referral_row(user_id):
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT 1 FROM referrals WHERE user_id = ?', (user_id,))
    if cursor.fetchone() is None:
        cursor.execute('INSERT INTO referrals (user_id) VALUES (?)', (user_id,))
        conn.commit()
    conn.close()


def register_referral(user_id, referrer_id):
    """Вызывается один раз - при первом /start?start=ref_<id> у пользователя,
    у которого ЕЩЁ НЕТ привязанного реферера (не переписывает существующую
    связь, не даёт указать самого себя рефералом).

    ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - 3 уровня вместо 2):
    теперь фиксируется ещё и referred_by_level3 (реферер реферера
    реферера) - тот же принцип, что и у level2: считается ОДИН раз на
    момент регистрации, не пересчитывается задним числом."""
    if referrer_id == user_id:
        return
    ensure_referral_row(user_id)
    ensure_referral_row(referrer_id)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT referred_by FROM referrals WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    if row and row[0] is not None:
        conn.close()
        return
    cursor.execute('SELECT referred_by, referred_by_level2 FROM referrals WHERE user_id = ?', (referrer_id,))
    r = cursor.fetchone()
    level2 = r[0] if r else None
    level3 = r[1] if r else None
    cursor.execute(
        'UPDATE referrals SET referred_by = ?, referred_by_level2 = ?, referred_by_level3 = ? WHERE user_id = ?',
        (referrer_id, level2, level3, user_id)
    )
    conn.commit()
    conn.close()


def get_referral_downline_count(user_id):
    """Сколько человек ВСЕГО в ветке пользователя, на любую глубину (3+
    уровня тоже считаются) - ТОЛЬКО для отображения, деньги по-прежнему
    начисляются лишь на 1 и 2 уровне (см. distribute_referral_earnings). По
    просьбе пользователя (20.09.2026): "добавить видимость 3+ уровня без
    денег". SQLite умеет рекурсивные CTE (WITH RECURSIVE) - обходим дерево
    referred_by вниз от user_id."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        '''
        WITH RECURSIVE downline(uid) AS (
            SELECT user_id FROM referrals WHERE referred_by = ?
            UNION ALL
            SELECT r.user_id FROM referrals r JOIN downline d ON r.referred_by = d.uid
        )
        SELECT COUNT(*) FROM downline
        ''',
        (user_id,)
    )
    count = cursor.fetchone()[0]
    conn.close()
    return count


def get_referral_stats(user_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT balance_kopecks, total_earned_kopecks, total_withdrawn_kopecks FROM referrals WHERE user_id = ?',
        (user_id,)
    )
    row = cursor.fetchone()
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by = ?', (user_id,))
    level1_count = cursor.fetchone()[0]
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by_level2 = ?', (user_id,))
    level2_count = cursor.fetchone()[0]
    # ДОБАВЛЕНО 23.09.2026 (3 уровня вместо 2, см. REFERRAL_RATES_PERCENT)
    cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by_level3 = ?', (user_id,))
    level3_count = cursor.fetchone()[0]
    conn.close()
    downline_total = get_referral_downline_count(user_id)
    return {
        'balance': (row[0] or 0) if row else 0,
        'total_earned': (row[1] or 0) if row else 0,
        'total_withdrawn': (row[2] or 0) if row else 0,
        'level1_count': level1_count,
        'level2_count': level2_count,
        'level3_count': level3_count,
        'downline_total': downline_total,  # видимость на всю глубину, без денег (4+ уровень)
    }


def get_referral_breakdown(user_id, limit=20):
    """Список прямых (1 уровень) рефералов - для каждого: сколько своих
    ПРЯМЫХ рефералов он привёл (это оплачиваемый 2 уровень) и сколько
    человек всего в ЕГО ветке на любую глубину (видимость 3+ уровня без
    денег - см. get_referral_downline_count)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT user_id FROM referrals WHERE referred_by = ? ORDER BY joined_at DESC LIMIT ?',
        (user_id, limit)
    )
    level1_ids = [r[0] for r in cursor.fetchall()]
    breakdown = []
    for uid in level1_ids:
        cursor.execute('SELECT COUNT(*) FROM referrals WHERE referred_by = ?', (uid,))
        sub_count = cursor.fetchone()[0]
        breakdown.append({
            'user_id': uid,
            'sub_referrals': sub_count,
            'branch_total': get_referral_downline_count(uid),
        })
    conn.close()
    return breakdown


def _credit_referral_earning(earner_id, source_id, level, amount_kopecks, order_id):
    if amount_kopecks <= 0:
        return 0
    ensure_referral_row(earner_id)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'INSERT INTO referral_earnings (earner_user_id, source_user_id, level, amount_kopecks, order_id) VALUES (?, ?, ?, ?, ?)',
        (earner_id, source_id, level, amount_kopecks, order_id)
    )
    cursor.execute(
        'UPDATE referrals SET balance_kopecks = balance_kopecks + ?, total_earned_kopecks = total_earned_kopecks + ? WHERE user_id = ?',
        (amount_kopecks, amount_kopecks, earner_id)
    )
    conn.commit()
    conn.close()
    return amount_kopecks


def get_referrer_type(user_id):
    """'legal_entity' или 'individual' (дефолт) - см. комментарий у
    REFERRAL_RATES_PERCENT. Определяет, по какой шкале процентов ЭТОТ
    человек получает начисления со своих рефералов (не зависит от того,
    кто его самого пригласил)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT referrer_type FROM referrals WHERE user_id = ?', (user_id,))
    row = cursor.fetchone()
    conn.close()
    referrer_type = row[0] if row else None
    return referrer_type if referrer_type in REFERRAL_RATES_PERCENT else REFERRAL_DEFAULT_TYPE

def set_referrer_type(user_id, referrer_type):
    if referrer_type not in REFERRAL_RATES_PERCENT:
        return False
    ensure_referral_row(user_id)
    conn = get_db_connection()
    conn.execute('UPDATE referrals SET referrer_type = ? WHERE user_id = ?', (referrer_type, user_id))
    conn.commit()
    conn.close()
    return True

# ==================== ЛИЧНЫЙ КАБИНЕТ ЮРЛИЦА ====================
# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - большое сообщение про
# "делаем личный кабинет у юрлица"). Механика привязки: у каждого юр.лица
# (строка в legal_entities) есть УНИКАЛЬНЫЙ пароль. Первый человек, который
# успешно ввёл этот пароль в диалоге "🏢 ЮРЛИЦО" (см.
# referral_legal_password_flow), становится owner_user_id - ТОЛЬКО он
# получает доступ к кнопке "🏛 КАБИНЕТ ЮРЛИЦА" (WebApp) и вообще к данным
# кабинета. Любой следующий, кто введёт ТОТ ЖЕ пароль, просто получает
# переключение своей персональной схемы начислений на 'legal_entity' (как
# было раньше), но НЕ становится владельцем кабинета и НЕ видит чужие
# данные. Пароли/названия компаний пользователь передаёт позже без
# редеплоя - через команду /add_legal_entity (см. admin_add_legal_entity
# ниже), ADMIN_TELEGRAM_ID-only.
def find_legal_entity_by_password(password):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT id, name, password, owner_user_id FROM legal_entities WHERE password = ?', (password,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    return {'id': row[0], 'name': row[1], 'password': row[2], 'owner_user_id': row[3]}


def claim_legal_entity_ownership(entity_id, user_id):
    """Если у юр.лица ещё нет владельца - закрепляет user_id владельцем
    (первый успешный ввод пароля). Если владелец уже есть - ничего не
    трогает (в т.ч. если владелец - тот же user_id, это просто no-op)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT owner_user_id FROM legal_entities WHERE id = ?', (entity_id,))
    row = cursor.fetchone()
    if row and row[0] is None:
        cursor.execute('UPDATE legal_entities SET owner_user_id = ? WHERE id = ?', (user_id, entity_id))
        conn.commit()
    conn.close()


def get_legal_entity_owned_by(user_id):
    """Юр.лицо, которым владеет этот user_id (создатель/первый введший
    пароль), или None, если он не владелец ни одного кабинета."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT id, name, password, owner_user_id, created_at FROM legal_entities WHERE owner_user_id = ?', (user_id,))
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    return {'id': row[0], 'name': row[1], 'password': row[2], 'owner_user_id': row[3], 'created_at': row[4]}


def add_legal_entity(name, password):
    """Создаёт новую запись юр.лица (пока без владельца - им станет первый,
    кто введёт этот пароль). Возвращает id или None, если такой пароль уже
    занят (UNIQUE)."""
    init_db()
    conn = get_db_connection()
    cursor = conn.cursor()
    try:
        cursor.execute('INSERT INTO legal_entities (name, password) VALUES (?, ?)', (name, password))
        conn.commit()
        new_id = cursor.lastrowid
    except sqlite3.IntegrityError:
        new_id = None
    conn.close()
    return new_id


def get_referral_downline_user_ids(user_id):
    """Тот же обход дерева, что get_referral_downline_count, но возвращает
    список конкретных user_id (любая глубина) - используется для вкладки
    "Водители" кабинета юрлица, фильтра карты "свои водители" и адресной
    рассылки push-уведомлений (см. handle_legal_cabinet_send_notification)."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        '''
        WITH RECURSIVE downline(uid) AS (
            SELECT user_id FROM referrals WHERE referred_by = ?
            UNION ALL
            SELECT r.user_id FROM referrals r JOIN downline d ON r.referred_by = d.uid
        )
        SELECT uid FROM downline
        ''',
        (user_id,)
    )
    ids = [r[0] for r in cursor.fetchall()]
    conn.close()
    return ids


