def add_legal_entity_rent_payment(car_id, driver_user_id, period, amount_kopecks, due_date, frequency=None, daily_rate_kopecks=None):
    init_db()
    if frequency not in LEGAL_ENTITY_RENT_FREQUENCY_LABELS:
        frequency = None
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'INSERT INTO legal_entity_car_rent_payments (car_id, driver_user_id, period, amount_kopecks, due_date, frequency, daily_rate_kopecks) '
        'VALUES (?, ?, ?, ?, ?, ?, ?)',
        (car_id, driver_user_id, period, amount_kopecks, due_date, frequency, daily_rate_kopecks)
    )
    conn.commit()
    new_id = cursor.lastrowid
    conn.close()
    return new_id


def set_legal_entity_rent_paid(payment_id, is_paid, marked_by):
    """Отметку "оплачено/не оплачено" ставит ТОЛЬКО владелец кабинета (см.
    handle_legal_cabinet_data_api - проверка entity.owner_user_id ДО вызова
    этой функции)."""
    conn = get_db_connection()
    conn.execute(
        'UPDATE legal_entity_car_rent_payments SET is_paid = ?, paid_at = ?, marked_by = ? WHERE id = ?',
        (1 if is_paid else 0, datetime.now(timezone.utc).isoformat() if is_paid else None, marked_by, payment_id)
    )
    conn.commit()
    conn.close()


def get_legal_entity_summary(entity_id):
    """Сводка для главного экрана кабинета - число машин, водителей на
    линии/не на линии (по shift в user_state, как и метка на карте), общий
    пробег (сумма mileage_km по всем машинам), сколько водителей должны
    сегодня оплатить аренду (ДОБАВЛЕНО 23.09.2026, прямая просьба
    пользователя - "сегодня должны оплатить аренду это выведи на главный
    экран такой-то количество водителей")."""
    cars = get_legal_entity_cars(entity_id)
    driver_ids = {c['driver_user_id'] for c in cars if c['driver_user_id']}
    on_line = 0
    off_line = 0
    for uid in driver_ids:
        state = user_state.get(uid) or {}
        if state.get('shift'):
            on_line += 1
        else:
            off_line += 1
    total_mileage = sum(c['mileage_km'] or 0 for c in cars)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT COUNT(DISTINCT p.driver_user_id) FROM legal_entity_car_rent_payments p '
        'JOIN legal_entity_cars c ON c.id = p.car_id '
        'WHERE c.entity_id = ? AND p.is_paid = 0 AND p.due_date = ? AND p.driver_user_id IS NOT NULL',
        (entity_id, datetime.now(timezone.utc).date().isoformat())
    )
    rent_due_today_count = cursor.fetchone()[0] or 0
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "такой-то
    # количество аренды водителей ещё не оплатили") - ВСЕГО водителей с
    # хотя бы одной неоплаченной записью аренды (независимо от due_date, в
    # отличие от rent_due_today_count выше - тот только про "сегодня").
    cursor.execute(
        'SELECT COUNT(DISTINCT p.driver_user_id) FROM legal_entity_car_rent_payments p '
        'JOIN legal_entity_cars c ON c.id = p.car_id '
        'WHERE c.entity_id = ? AND p.is_paid = 0 AND p.driver_user_id IS NOT NULL',
        (entity_id,)
    )
    rent_unpaid_total_count = cursor.fetchone()[0] or 0
    conn.close()
    return {
        'cars_count': len(cars),
        'drivers_on_line': on_line,
        'drivers_off_line': off_line,
        'total_mileage_km': round(total_mileage, 1),
        'rent_due_today_count': rent_due_today_count,
        'rent_unpaid_total_count': rent_unpaid_total_count,
    }


LEGAL_ENTITY_EMPLOYMENT_TYPES = {
    'ip': 'Работает как ИП',
    'self_employed': 'Самозанятый',
    'none': 'Без трудоустройства',
}


def get_legal_entity_driver_profile(entity_id, driver_user_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT last_name, first_name, patronymic, birth_date, gender, phone1, phone2, '
        'passport_data, registration_address, employment_type, comment '
        'FROM legal_entity_driver_profiles WHERE entity_id = ? AND driver_user_id = ?',
        (entity_id, driver_user_id)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return None
    keys = ['last_name', 'first_name', 'patronymic', 'birth_date', 'gender', 'phone1', 'phone2',
            'passport_data', 'registration_address', 'employment_type', 'comment']
    return dict(zip(keys, row))


def get_legal_entity_driver_profiles_map(entity_id):
    """Все анкеты водителей юр.лица сразу, {driver_user_id: {last_name,
    first_name, patronymic}} - используется для подписи ФИО на карте (см.
    _enrich_positions_with_fleet_info) - только ФИО, остальные поля анкеты
    (паспорт/прописка и т.д.) на карту не нужны."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT driver_user_id, last_name, first_name, patronymic FROM legal_entity_driver_profiles WHERE entity_id = ?',
        (entity_id,)
    )
    rows = cursor.fetchall()
    conn.close()
    return {r[0]: {'last_name': r[1], 'first_name': r[2], 'patronymic': r[3]} for r in rows}


def _enrich_positions_with_fleet_info(positions, entity_id):
    """Добавляет к позициям водителей (см. get_map_positions(include_user_id=True))
    данные из карточки машины (госномер/марка/модель/цвет) и ФИО из анкеты
    водителя (см. LEGAL_ENTITY_DRIVER_PROFILE_FIELDS) - прямая просьба
    пользователя (23.09.2026): "над каждым водителем обязательно
    подписывается номер автомобиля ФИО водителя модель и марка и цвет".
    user_id убирается из каждой позиции ПОСЛЕ обогащения - наружу он не
    уходит, только человекочитаемые поля."""
    cars = get_legal_entity_cars(entity_id)
    car_by_driver = {c['driver_user_id']: c for c in cars if c['driver_user_id']}
    profiles = get_legal_entity_driver_profiles_map(entity_id)
    result = []
    for p in positions:
        uid = p.pop('user_id', None)
        car = car_by_driver.get(uid)
        profile = profiles.get(uid)
        fio_parts = [profile.get(k) for k in ('last_name', 'first_name', 'patronymic')] if profile else []
        fio = ' '.join(part for part in fio_parts if part) or None
        p['fleet_plate'] = car['plate'] if car else None
        p['fleet_make'] = car['make'] if car else None
        p['fleet_model'] = car['model'] if car else None
        p['fleet_color'] = car['color'] if car else None
        p['fleet_driver_name'] = fio
        result.append(p)
    return result


LEGAL_ENTITY_DRIVER_PROFILE_FIELDS = [
    'last_name', 'first_name', 'patronymic', 'birth_date', 'gender', 'phone1', 'phone2',
    'passport_data', 'registration_address', 'employment_type', 'comment',
]
LEGAL_ENTITY_DRIVER_PROFILE_MAX_LEN = {
    'last_name': 60, 'first_name': 60, 'patronymic': 60, 'birth_date': 10, 'gender': 10,
    'phone1': 30, 'phone2': 30, 'passport_data': 60, 'registration_address': 200,
    'employment_type': 20, 'comment': 1000,
}


def save_legal_entity_driver_profile(entity_id, driver_user_id, fields):
    """Апсёрт анкеты водителя (см. таблицу legal_entity_driver_profiles в
    init_db) - fields - словарь с любым подмножеством
    LEGAL_ENTITY_DRIVER_PROFILE_FIELDS, отсутствующие поля не трогаем
    (COALESCE от старого значения)."""
    init_db()
    clean = {}
    for key in LEGAL_ENTITY_DRIVER_PROFILE_FIELDS:
        if key in fields:
            val = fields.get(key)
            val = str(val).strip()[:LEGAL_ENTITY_DRIVER_PROFILE_MAX_LEN[key]] if val not in (None, '') else None
            clean[key] = val
    if clean.get('employment_type') is not None and clean['employment_type'] not in LEGAL_ENTITY_EMPLOYMENT_TYPES:
        clean.pop('employment_type', None)
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT 1 FROM legal_entity_driver_profiles WHERE entity_id = ? AND driver_user_id = ?',
        (entity_id, driver_user_id)
    )
    exists = cursor.fetchone() is not None
    if exists:
        set_clause = ', '.join(f'{k} = ?' for k in clean) + ', updated_at = CURRENT_TIMESTAMP'
        cursor.execute(
            f'UPDATE legal_entity_driver_profiles SET {set_clause} WHERE entity_id = ? AND driver_user_id = ?',
            list(clean.values()) + [entity_id, driver_user_id]
        )
    else:
        cols = ['entity_id', 'driver_user_id'] + list(clean.keys())
        placeholders = ', '.join('?' for _ in cols)
        cursor.execute(
            f'INSERT INTO legal_entity_driver_profiles ({", ".join(cols)}) VALUES ({placeholders})',
            [entity_id, driver_user_id] + list(clean.values())
        )
    conn.commit()
    conn.close()
    return True


# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "если аренда будет не
# оплачена он будет присылать три раза в сутки push уведомления что оплатить
# аренду и присылать ссылку на... главного кто будет следить кому надо будет
# оплачивать") - фоновая проверка (см. legal_entity_rent_reminder_checker,
# зарегистрирована в main() рядом с fuel_reminder_checker) - для каждой
# неоплаченной записи аренды шлёт водителю пуш, не чаще 3 раз в календарные
# сутки (~раз в LEGAL_ENTITY_RENT_REMINDER_CHECK_INTERVAL_MINUTES * N),
# со ссылкой на владельца кабинета (tg://user?id=), кому нужно платить.
LEGAL_ENTITY_RENT_REMINDER_CHECK_INTERVAL_MINUTES = 20
LEGAL_ENTITY_RENT_REMINDERS_PER_DAY = 3
LEGAL_ENTITY_RENT_REMINDER_MIN_GAP_HOURS = 7  # чуть меньше 24/3=8, чтобы не промахнуться мимо третьего окна


def get_unpaid_legal_entity_rent_payments():
    """Все неоплаченные записи аренды (по всем юр.лицам сразу), с
    driver_user_id и данными владельца/машины - используется только
    планировщиком напоминаний."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT p.id, p.driver_user_id, p.period, p.amount_kopecks, p.due_date, '
        'c.plate, c.model, e.name, e.owner_user_id '
        'FROM legal_entity_car_rent_payments p '
        'JOIN legal_entity_cars c ON c.id = p.car_id '
        'JOIN legal_entities e ON e.id = c.entity_id '
        'WHERE p.is_paid = 0 AND p.driver_user_id IS NOT NULL'
    )
    rows = cursor.fetchall()
    conn.close()
    return [
        {'id': r[0], 'driver_user_id': r[1], 'period': r[2], 'amount_kopecks': r[3] or 0,
         'due_date': r[4], 'plate': r[5], 'model': r[6], 'entity_name': r[7], 'owner_user_id': r[8]}
        for r in rows
    ]


def _legal_entity_rent_reminder_tracker(payment_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT sent_count_today, last_sent_at, reminder_date FROM legal_entity_rent_reminders_sent WHERE rent_payment_id = ?',
        (payment_id,)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return {'sent_count_today': 0, 'last_sent_at': None, 'reminder_date': None}
    return {'sent_count_today': row[0] or 0, 'last_sent_at': row[1], 'reminder_date': row[2]}


def _legal_entity_rent_reminder_mark_sent(payment_id, car_id, sent_count_today, today_str):
    conn = get_db_connection()
    conn.execute(
        'INSERT INTO legal_entity_rent_reminders_sent (rent_payment_id, car_id, sent_count_today, last_sent_at, reminder_date) '
        'VALUES (?, ?, ?, ?, ?) '
        'ON CONFLICT(rent_payment_id) DO UPDATE SET sent_count_today = excluded.sent_count_today, '
        'last_sent_at = excluded.last_sent_at, reminder_date = excluded.reminder_date',
        (payment_id, car_id, sent_count_today, datetime.now(timezone.utc).isoformat(), today_str)
    )
    conn.commit()
    conn.close()


async def _send_legal_entity_rent_reminder(payment):
    amount_rub = round((payment['amount_kopecks'] or 0) / 100)
    car_label = (payment['plate'] or '') + (f" {payment['model']}" if payment['model'] else '')
    text = (
        f"⚠️ *Не оплачена аренда*\n\n"
        f"🚗 {car_label.strip() or 'машина'}\n"
        f"🏢 {payment['entity_name']}\n"
        f"📅 Период: {payment['period']}\n"
        f"💰 Сумма: {amount_rub}₽\n"
        f"⏰ Срок: {payment['due_date'] or '—'}\n\n"
        f"Пожалуйста, оплати аренду и сообщи об этом."
    )
    markup = None
    if payment.get('owner_user_id'):
        markup = InlineKeyboardMarkup(inline_keyboard=[[
            InlineKeyboardButton(text="✍️ Написать по аренде", url=f"tg://user?id={payment['owner_user_id']}")
        ]])
    try:
        await bot.send_message(payment['driver_user_id'], text, parse_mode='Markdown', reply_markup=markup)
    except Exception:
        logger.warning(f"⚠️ Не удалось отправить напоминание об аренде user_id={payment['driver_user_id']}")


async def check_legal_entity_rent_reminders():
    if not bot:
        return
    today_str = datetime.now(timezone.utc).date().isoformat()
    for payment in get_unpaid_legal_entity_rent_payments():
        tracker = _legal_entity_rent_reminder_tracker(payment['id'])
        sent_count_today = tracker['sent_count_today'] if tracker['reminder_date'] == today_str else 0
        if sent_count_today >= LEGAL_ENTITY_RENT_REMINDERS_PER_DAY:
            continue
        last_sent_at = tracker['last_sent_at']
        if last_sent_at:
            try:
                elapsed_hours = (datetime.now(timezone.utc) - datetime.fromisoformat(last_sent_at)).total_seconds() / 3600
            except Exception:
                elapsed_hours = LEGAL_ENTITY_RENT_REMINDER_MIN_GAP_HOURS + 1
            if elapsed_hours < LEGAL_ENTITY_RENT_REMINDER_MIN_GAP_HOURS:
                continue
        await _send_legal_entity_rent_reminder(payment)
        # car_id не нужен для самой логики выше, но храним для наглядности в БД
        conn = get_db_connection()
        cursor = conn.cursor()
        cursor.execute('SELECT car_id FROM legal_entity_car_rent_payments WHERE id = ?', (payment['id'],))
        car_row = cursor.fetchone()
        conn.close()
        _legal_entity_rent_reminder_mark_sent(payment['id'], car_row[0] if car_row else None, sent_count_today + 1, today_str)


async def legal_entity_rent_reminder_checker():
    """Фоновая задача (см. asyncio.create_task в main(), рядом с
    fuel_reminder_checker) - раз в LEGAL_ENTITY_RENT_REMINDER_CHECK_INTERVAL_MINUTES
    проверяет неоплаченную аренду и шлёт напоминания (см.
    check_legal_entity_rent_reminders)."""
    while True:
        try:
            await check_legal_entity_rent_reminders()
        except Exception:
            logger.exception("❌ Ошибка фоновой проверки напоминаний об аренде юрлица")
        await asyncio.sleep(LEGAL_ENTITY_RENT_REMINDER_CHECK_INTERVAL_MINUTES * 60)


# ==================== РЕЗЕРВНОЕ КОПИРОВАНИЕ БАЗЫ ====================
# ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "насколько вот эти
# базы устойчивые... можно ли как-то делать бэкап этих баз... дублировать
# их... давай подумаем сразу резервирование и безопасности этих баз").
#
# КАК СЕЙЧАС УСТРОЕНО ХРАНЕНИЕ (см. _resolve_db_file выше): если у сервиса
# в Railway подключён Persistent Volume, смонтированный в /data, основная
# БД (taxi_queue.db - в НЕЙ же теперь и вся новая юрлицо-логика:
# legal_entities/legal_entity_cars/legal_entity_car_rent_payments/
# legal_entity_driver_profiles) переживает редеплой. Но это ОДИН файл на
# ОДНОМ диске - он не защищён от порчи самого диска Railway, случайного
# удаления volume, обрыва записи при крэше процесса посреди транзакции и
# т.п. Это и есть риск, о котором пишет пользователь - "резко могут
# рухнуть, пропасть".
#
# РЕШЕНИЕ (без дополнительной инфраструктуры вроде S3, которой сейчас нет
# в проекте): автоматический снэпшот базы через SQLite Backup API (даёт
# консистентную копию, даже если в это время идёт запись - в отличие от
# простого копирования файла) отправляется ДОКУМЕНТОМ в Telegram
# ADMIN_TELEGRAM_ID раз в DB_BACKUP_INTERVAL_HOURS часов. Telegram - это
# физически ДРУГОЕ хранилище (серверы Telegram), не связанное с Railway,
# так что при потере volume целиком копия всё равно остаётся - именно то
# "дублирование", о котором просит пользователь. Плюс команда /backup_now
# для бэкапа по требованию в любой момент.
DB_BACKUP_INTERVAL_HOURS = 6  # 4 копии в сутки


async def backup_database_now(reason="плановый"):
    """Снимает консистентный снэпшот DB_FILE (sqlite3 Backup API - безопасно
    даже при параллельной записи, в отличие от обычного copy файла) и
    отправляет его ADMIN_TELEGRAM_ID документом. Синхронная часть (сам backup
    в SQLite - блокирующая операция) уходит в отдельный поток, чтобы не
    вешать event loop бота на время копирования."""
    if not bot or not ADMIN_TELEGRAM_ID:
        return False
    ts = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S')
    backup_path = f"{DB_FILE}.backup_{ts}.db"

    def _do_backup():
        src = sqlite3.connect(DB_FILE)
        dst = sqlite3.connect(backup_path)
        try:
            src.backup(dst)
        finally:
            dst.close()
            src.close()
        return os.path.getsize(backup_path)

    try:
        size_bytes = await asyncio.to_thread(_do_backup)
    except Exception:
        logger.exception("❌ Не удалось сделать резервную копию базы")
        try:
            await bot.send_message(ADMIN_TELEGRAM_ID, "⚠️ Резервное копирование базы не удалось - смотри логи Railway.")
        except Exception:
            pass
        return False

    try:
        await bot.send_document(
            ADMIN_TELEGRAM_ID,
            FSInputFile(backup_path, filename=f"taxi_queue_backup_{ts}.db"),
            caption=f"💾 Резервная копия базы ({reason}), {round(size_bytes / 1024 / 1024, 1)} МБ, {ts} UTC",
        )
        ok = True
    except Exception:
        logger.exception("❌ Не удалось отправить резервную копию базы в Telegram")
        ok = False
    finally:
        try:
            os.remove(backup_path)
        except Exception:
            pass
    return ok


async def db_backup_checker():
    """Фоновая задача (см. asyncio.create_task в main()) - раз в
    DB_BACKUP_INTERVAL_HOURS часов отправляет свежий бэкап базы админу (см.
    backup_database_now)."""
    while True:
        await asyncio.sleep(DB_BACKUP_INTERVAL_HOURS * 3600)
        try:
            await backup_database_now(reason="плановый")
        except Exception:
            logger.exception("❌ Ошибка фоновой задачи резервного копирования базы")


@router.message(Command("backup_now"))
async def admin_backup_now(message: types.Message):
    """Бэкап базы по требованию (см. backup_database_now) - только
    ADMIN_TELEGRAM_ID, тот же паттерн проверки, что у /referral_paid."""
    if not ADMIN_TELEGRAM_ID or str(message.from_user.id) != str(ADMIN_TELEGRAM_ID):
        return
    await message.answer("⏳ Делаю резервную копию базы...")
    ok = await backup_database_now(reason="по команде /backup_now")
    if not ok:
        await message.answer("❌ Не получилось - смотри логи Railway.")


def distribute_referral_earnings(payer_user_id, amount_kopecks, order_id):
    """Вызывается из confirm_subscription_payment при каждом подтверждённом
    платеже - начисляет 1, 2 и 3 уровню (если у плательщика есть
    реферер(ы) на этой глубине). Возвращает список (earner_id, level,
    начислено_копеек) для рассылки уведомлений вызывающим кодом (сам ничего
    не шлёт - синхронная функция).

    ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - 2 схемы начислений,
    3 уровня): раньше был фиксированный процент 1 уровня + доля от него на
    2 уровне, один на всех. Теперь на каждом уровне берётся ПРЯМОЙ процент
    от суммы платежа - какой именно, зависит от referrer_type КОНКРЕТНОГО
    получателя на этом уровне (см. get_referrer_type/REFERRAL_RATES_PERCENT) -
    так что юр.лицо и обычный пользователь, стоящие на одном и том же
    уровне цепочки, получат разные суммы с одного и того же платежа."""
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute(
        'SELECT referred_by, referred_by_level2, referred_by_level3 FROM referrals WHERE user_id = ?',
        (payer_user_id,)
    )
    row = cursor.fetchone()
    conn.close()
    if not row:
        return []
    notifications = []
    for level, earner_id in enumerate(row, start=1):
        if not earner_id:
            continue
        rates = REFERRAL_RATES_PERCENT[get_referrer_type(earner_id)]
        rate_percent = rates[level - 1]
        if rate_percent <= 0:
            continue
        amount = amount_kopecks * rate_percent // 100
        credited = _credit_referral_earning(earner_id, payer_user_id, level, amount, order_id)
        if credited:
            notifications.append((earner_id, level, credited))
    return notifications


REFERRAL_SHARE_TEXT_TEMPLATE = (
    "Пользуюсь Taxi Helper - бот-помощник для водителей такси/курьеров/грузового такси: "
    "подсказывает, куда ехать и когда самый спрос, следит за очередями в аэропортах, считает доход за смену. "
    "Заходи по ссылке 👇\n{link}"
)


def referral_menu_keyboard(referral_link, current_type=REFERRAL_DEFAULT_TYPE, user_id=None):
    # "🔗 МОЯ ССЫЛКА"/"📤 ПОДЕЛИТЬСЯ ССЫЛКОЙ" - по прямой просьбе пользователя
    # (20.09.2026: "нужна кнопка... чтобы люди понимали какую ссылку давать
    # чтобы делиться"). "Поделиться" - через switch_inline_query: открывает
    # у пользователя список его чатов Telegram с уже готовым текстом+ссылкой,
    # остаётся выбрать, кому переслать - самый надёжный способ "поделиться"
    # для обычной кнопки бота (Telegram не даёт ботам напрямую копировать
    # текст в буфер обмена). "Моя ссылка" - просто прислать ссылку отдельным
    # сообщением, чтобы было удобно скопировать долгим нажатием.
    #
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "сразу выведи две
    # кнопки с реферальной программой для двух категорий под кнопкой
    # реферальная программа"): выбор схемы начислений ПРЯМО здесь, сверху -
    # "Юр.лицо" защищена паролем (см. referral_category_legal_start/
    # REFERRAL_LEGAL_ENTITY_PASSWORD), "Обычная" переключает сразу без
    # подтверждения. Текущий выбор отмечен галочкой.
    share_text = REFERRAL_SHARE_TEXT_TEMPLATE.format(link=referral_link)
    # ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "поменяй где юр лица
    # убери там проценты чтобы не видели обычные юзеры") - проценты схемы
    # "юр.лицо" больше не показываются в кнопке (обычные пользователи не
    # должны видеть, насколько она выгоднее). У "Обычной" проценты оставлены -
    # это ставка самого пользователя, её скрывать незачем.
    individual_label = ("✅ " if current_type == 'individual' else "") + "👤 Обычная (30/15/5%)"
    # ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "по кнопке юрлицо
    # его надо с большими буквами сделать ЮРЛИЦО") - заглавные буквы.
    legal_label = ("✅ " if current_type == 'legal_entity' else "") + "🏢 ЮРЛИЦО"
    # ИЗМЕНЕНО 23.09.2026 (прямая просьба пользователя - "убери личный
    # кабинет в кнопку юрлицо"): раньше "🏛 ЛИЧНЫЙ КАБИНЕТ ЮРЛИЦА" была
    # ОТДЕЛЬНОЙ строкой под "🏢 ЮРЛИЦО" - теперь это ОДНА кнопка. Если
    # человек уже владеет кабинетом (get_legal_entity_owned_by) И у него
    # активна платная подписка юрлица (is_legal_entity_referral_subscription_
    # active) - сама кнопка "ЮРЛИЦО" становится web_app-ссылкой на кабинет
    # (открывает сразу, без лишнего тапа). Иначе - как раньше, callback на
    # referral_category_legal_start (пароль компании/оплата подписки) - у
    # web_app-кнопки нет серверного колбэка, так что кнопку НЕЛЬЗЯ сделать
    # web_app, если подписка вдруг ещё не оплачена (иначе платный кабинет
    # открывался бы в обход paywall) - проверка обязательна ДО переключения
    # в web_app-режим.
    # ИСПРАВЛЕНО 23.09.2026 (найдено при проверке логики оплат рефералов):
    # схема 'admin' (см. admin_referral_password_flow) владеет кабинетом
    # (owned_entity), но НИКОГДА не платит SUBSCRIPTION_GROUP_LEGAL_ENTITY_
    # REFERRAL (её кабинет бесплатный, "админский бэкдор") - без этого
    # условия is_legal_entity_referral_subscription_active была бы False
    # для админа, кнопка падала бы в callback-ветку и просила бы пароль/
    # оплату заново вместо прямой ссылки на уже свой бесплатный кабинет.
    owned_entity = get_legal_entity_owned_by(user_id) if user_id is not None else None
    cabinet_unlocked = current_type == 'admin' or is_legal_entity_referral_subscription_active(user_id)
    if owned_entity and PUBLIC_URL and cabinet_unlocked:
        cabinet_url = f"{PUBLIC_URL}{LEGAL_CABINET_WEBAPP_PATH}"
        legal_button = InlineKeyboardButton(text=legal_label, web_app=WebAppInfo(url=cabinet_url))
    else:
        legal_button = InlineKeyboardButton(text=legal_label, callback_data="referral_category_legal_start")
    rows = [
        [InlineKeyboardButton(text=individual_label, callback_data="referral_category_individual")],
        [legal_button],
    ]
    # ДОБАВЛЕНО 23.09.2026 (прямая просьба пользователя - "там появляется
    # кнопка внутри личный кабинет и подписка") - кнопка статуса/продления
    # платной подписки юрлица (см. send_legal_entity_referral_paywall). У
    # схемы 'admin' (Фантом) своя бесплатная подписка (SUBSCRIPTION_GROUP_
    # TAXI_ULTIMA/COURIER_CARGO через grant_free_month) - эта кнопка ей не
    # нужна.
    if owned_entity and current_type == 'legal_entity':
        rows.append([InlineKeyboardButton(text="💳 ПОДПИСКА ЮРЛИЦА", callback_data="legal_entity_sub_status")])
    rows += [
        [InlineKeyboardButton(text="🔗 МОЯ ССЫЛКА", callback_data="referral_link_show")],
        # "📱 QR-КОД ССЫЛКИ" - по прямой просьбе пользователя (22.09.2026,
        # после подготовки презентации бота - "добавить возможность каждому
        # загружать свою презентацию со своим QR-кодом со своей ссылкой по
        # кнопке чтобы люди могли подключаться") - каждый пользователь может
        # получить QR-код СВОЕЙ персональной реферальной ссылки одним нажатием
        # (см. referral_qr_show/build_referral_qr_png ниже), чтобы показывать
        # его на встречах/презентациях или клеить на авто - не нужно ничего
        # генерировать вручную на стороне.
        [InlineKeyboardButton(text="📱 QR-КОД ССЫЛКИ", callback_data="referral_qr_show")],
        # "📥 СКАЧАТЬ ПРЕЗЕНТАЦИЮ" - по прямой просьбе пользователя (22.09.2026,
        # "сделай без куар кода в рефералка скачать презентацию и загружай пдф
        # файл") - отправляет готовый PDF презентации бота (без QR-кода, чтобы
        # получатель подключался по персональной ссылке приглашающего, а не по
        # QR с чужого CTA-слайда) прямо файлом в чат, см.
        # PRESENTATION_PDF_PATH/referral_download_presentation ниже.
        [InlineKeyboardButton(text="📥 СКАЧАТЬ ПРЕЗЕНТАЦИЮ", callback_data="referral_download_presentation")],
        [InlineKeyboardButton(text="📤 ПОДЕЛИТЬСЯ ССЫЛКОЙ", switch_inline_query=share_text)],
        [InlineKeyboardButton(text="📋 МОИ РЕФЕРАЛЫ", callback_data="referral_list")],
        [InlineKeyboardButton(text="💸 ВЫВЕСТИ СРЕДСТВА", callback_data="referral_withdraw_start")],
        # ПЕРЕНЕСЕНО 23.09.2026 (прямая просьба пользователя - "фантом
        # перенеси в рефералов кнопку") - раньше "👻 ФАНТОМ" была на экранах
        # подписки (subscription_paywall_keyboard), теперь здесь, в меню
        # реферальной программы. Сама логика (PHANTOM_SUBSCRIPTION_PASSWORD/
        # phantom_start/phantom_password_flow, см. блок "ПЛАТНАЯ ПОДПИСКА"
        # выше) не менялась - только расположение кнопки, callback_data тот
        # же ("phantom_start"), поэтому хендлер трогать не нужно.
        # ПЕРЕНЕСЕНО 23.09.2026 (прямая просьба пользователя - "занеси кнопку
        # админ в фантом будет с двойной верефикацией") - отдельная кнопка
        # "🔐 АДМИН" убрана, доступ в админ-панель теперь спрятан ВНУТРИ
        # "👻 ФАНТОМ" (см. phantom_password_flow ниже): если ввести
        # ADMIN_PANEL_PASSWORD вместо обычного пароля Фантома, бот просит
        # ввести его ЕЩЁ РАЗ (двойная верификация) и только после второго
        # совпадения показывает админ-панель - отдельной кнопки, которая
        # выдавала бы саму возможность существования админки, больше нет.
        [InlineKeyboardButton(text="👻 ФАНТОМ", callback_data="phantom_start")],
    ]
    return InlineKeyboardMarkup(inline_keyboard=rows)


def get_referral_link(bot_username, user_id):
    return f"https://t.me/{bot_username}?start=ref_{user_id}"


def referral_withdraw_cancel_keyboard():
    return ReplyKeyboardMarkup(resize_keyboard=True, keyboard=[[KeyboardButton(text="❌ ОТМЕНА")]])


@router.message(lambda message: message.text == "🤝 РЕФЕРАЛЬНАЯ ПРОГРАММА")
async def show_referral_program(message: types.Message):
    user_id = message.from_user.id
    ensure_referral_row(user_id)
    if not REFERRAL_PROGRAM_LIVE:
        await message.answer(
            "🤝 *Реферальная программа*\n\n"
            "Скоро здесь можно будет приглашать друзей по своей ссылке и получать процент с их подписки. "
            "Раздел в разработке — совсем скоро заработает 🚀",
            parse_mode='Markdown'
        )
        return
    stats = get_referral_stats(user_id)
    me = await bot.get_me()
    link = get_referral_link(me.username, user_id)
    # ИЗМЕНЕНО 22.09.2026 (прямая просьба пользователя - "поработай над
    # визуальной частью ... по тому что не в миниапе") - раньше это был
    # сплошной абзац без деления на смысловые блоки. Разбито на секции тем
    # же общим разделителем WHERE_TO_GO_DIVIDER, что уже используется в
    # "Куда ехать"/"ДЕНЬ - ИТОГ" - ссылка / статистика рефералов / баланс /
    # как это работает, читается быстрее одним взглядом.
    # ИЗМЕНЕНО 23.09.2026 (3 уровня + 2 схемы начислений, см.
    # REFERRAL_RATES_PERCENT/get_referrer_type) - показываем СВОЮ шкалу
    # процентов (обычную 30/15/5 или, для юр.лиц, 40/30/20), а не одну
    # зашитую формулу на всех.
    my_rates = REFERRAL_RATES_PERCENT[get_referrer_type(user_id)]
    text = (
        "🤝 *Реферальная программа*\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"🔗 Твоя ссылка (отправляй друзьям):\n`{link}`\n\n"
        f"👥 Рефералов 1-го уровня: {stats['level1_count']}\n"
        f"👥 Рефералов 2-го уровня: {stats['level2_count']}\n"
        f"👥 Рефералов 3-го уровня: {stats['level3_count']}\n"
        f"🌳 Всего людей в твоей ветке (любая глубина): {stats['downline_total']}\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"💰 Баланс: {stats['balance'] / 100:.0f}₽\n"
        f"📈 Всего заработано: {stats['total_earned'] / 100:.0f}₽\n"
        f"📤 Всего выведено: {stats['total_withdrawn'] / 100:.0f}₽\n"
        f"{WHERE_TO_GO_DIVIDER}\n\n"
        f"_Как это работает:_ {my_rates[0]}% с каждого ежемесячного платежа приглашённого "
        f"тобой напрямую (1 уровень), {my_rates[1]}% с платежей его рефералов (2 уровень) и "
        f"{my_rates[2]}% с платежей рефералов 2 уровня (3 уровень) - прямой процент от суммы "
        f"платежа на каждом уровне. Начисляется каждый месяц, пока реферал платит подписку. "
        f"Дальше 3 уровня деньги не идут, но всю ветку целиком видно в «📋 Мои рефералы».\n\n"
        f"Вывод - только на карту, комиссия сервиса {REFERRAL_WITHDRAWAL_FEE_PERCENT}%, "
        f"минимум {REFERRAL_MIN_WITHDRAWAL_RUB}₽."
    )
    await message.answer(text, reply_markup=referral_menu_keyboard(link, get_referrer_type(user_id), user_id), parse_mode='Markdown')


