def mark_referral_withdrawal_paid(withdrawal_id):
    conn = get_db_connection()
    cursor = conn.cursor()
    cursor.execute('SELECT user_id, payout_kopecks, status FROM referral_withdrawals WHERE id = ?', (withdrawal_id,))
    row = cursor.fetchone()
    if not row or row[2] != 'pending':
        conn.close()
        return None
    user_id, payout_kopecks, _ = row
    cursor.execute(
        "UPDATE referral_withdrawals SET status = 'paid', processed_at = ? WHERE id = ?",
        (_sub_format(_sub_now()), withdrawal_id)
    )
    cursor.execute(
        'UPDATE referrals SET total_withdrawn_kopecks = total_withdrawn_kopecks + ? WHERE user_id = ?',
        (payout_kopecks, user_id)
    )
    conn.commit()
    conn.close()
    return {'user_id': user_id, 'payout_kopecks': payout_kopecks}


# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "надо сделать механику
# чтобы бот считал чистую прибыль кампании для моего аккаунта со всех
# программ реферальных"): считает чистую прибыль по обеим реферальным
# схемам вместе (individual + legal_entity - они делят одни и те же таблицы
# subscription_payments/referral_earnings/referral_withdrawals, отдельного
# разреза по схеме не просили). Формула (уточнена с пользователем через
# AskUserQuestion):
#   чистая прибыль = доход от подписок (subscription_payments, только
#   реально подтверждённые - status='CONFIRMED') минус все начисленные
#   рефералам выплаты (referral_earnings.amount_kopecks - списывается со
#   счёта компании независимо от того, вывёл ли реферал деньги себе) плюс
#   доход с комиссии за вывод (referral_withdrawals.fee_kopecks, только
#   по факту ВЫПЛАЧЕННЫМ заявкам - status='paid', т.к. комиссия реально
#   "оседает" только когда бот отправил деньги и удержал свои 3%).
# period='all' - за всё время работы бота, period='month' - с 1-го числа
# текущего месяца (UTC, тот же часовой пояс, что и everywhere в файле).
def compute_campaign_profit(period='all'):
    conn = get_db_connection()
    cursor = conn.cursor()
    if period == 'month':
        period_start = datetime.utcnow().strftime('%Y-%m-01 00:00:00')
        date_filter_payments = 'AND confirmed_at >= ?'
        date_filter_earnings = 'AND created_at >= ?'
        date_filter_withdrawals = 'AND processed_at >= ?'
        params = (period_start,)
    else:
        date_filter_payments = ''
        date_filter_earnings = ''
        date_filter_withdrawals = ''
        params = ()

    cursor.execute(
        f"SELECT COALESCE(SUM(amount_kopecks), 0) FROM subscription_payments WHERE status = 'CONFIRMED' {date_filter_payments}",
        params
    )
    subscription_revenue_kopecks = cursor.fetchone()[0]

    cursor.execute(
        f"SELECT COALESCE(SUM(amount_kopecks), 0) FROM referral_earnings WHERE 1=1 {date_filter_earnings}",
        params
    )
    referral_payouts_kopecks = cursor.fetchone()[0]

    cursor.execute(
        f"SELECT COALESCE(SUM(fee_kopecks), 0) FROM referral_withdrawals WHERE status = 'paid' {date_filter_withdrawals}",
        params
    )
    withdrawal_fee_income_kopecks = cursor.fetchone()[0]

    conn.close()
    net_profit_kopecks = subscription_revenue_kopecks - referral_payouts_kopecks + withdrawal_fee_income_kopecks
    return {
        'subscription_revenue_kopecks': subscription_revenue_kopecks,
        'referral_payouts_kopecks': referral_payouts_kopecks,
        'withdrawal_fee_income_kopecks': withdrawal_fee_income_kopecks,
        'net_profit_kopecks': net_profit_kopecks,
    }


# ДОБАВЛЕНО 22.09.2026 (прямая просьба пользователя - "надо так же прописывать
# сумму к выплате рефералам по отдельным схемам чтобы понимать сколько денег
# хранить для выплат"): резерв - это НЕ то же самое, что referral_payouts_kopecks
# выше (сколько уже НАЧИСЛЕНО за период) - это сколько денег прямо сейчас
# "висит" на балансах рефералов и ещё не выведено (referrals.balance_kopecks -
# уменьшается при каждом выводе, см. request_referral_withdrawal), плюс уже
# поданные, но ещё не отмеченные оплаченными заявки на вывод
# (referral_withdrawals.status='pending', payout_kopecks - то, что реально
# уйдёт со счёта, уже за вычетом комиссии). Разрез по схемам - через
# referrals.referrer_type (см. REFERRAL_RATES_PERCENT/set_referrer_type).
# Это снимок на текущий момент (не за период), поэтому в compute_campaign_profit
# не встроено, а считается отдельно.
def compute_referral_reserve_by_scheme():
    conn = get_db_connection()
    cursor = conn.cursor()
    reserve = {scheme: 0 for scheme in REFERRAL_RATES_PERCENT}
    cursor.execute("SELECT COALESCE(referrer_type, ?), COALESCE(SUM(balance_kopecks), 0) FROM referrals GROUP BY 1", (REFERRAL_DEFAULT_TYPE,))
    for referrer_type, balance_kopecks in cursor.fetchall():
        reserve[referrer_type if referrer_type in reserve else REFERRAL_DEFAULT_TYPE] = reserve.get(referrer_type if referrer_type in reserve else REFERRAL_DEFAULT_TYPE, 0) + balance_kopecks
    cursor.execute('''
        SELECT COALESCE(r.referrer_type, ?), COALESCE(SUM(w.payout_kopecks), 0)
        FROM referral_withdrawals w
        LEFT JOIN referrals r ON r.user_id = w.user_id
        WHERE w.status = 'pending'
        GROUP BY 1
    ''', (REFERRAL_DEFAULT_TYPE,))
    pending_withdrawals = {scheme: 0 for scheme in REFERRAL_RATES_PERCENT}
    for referrer_type, payout_kopecks in cursor.fetchall():
        pending_withdrawals[referrer_type if referrer_type in pending_withdrawals else REFERRAL_DEFAULT_TYPE] = pending_withdrawals.get(referrer_type if referrer_type in pending_withdrawals else REFERRAL_DEFAULT_TYPE, 0) + payout_kopecks
    conn.close()
    return {
        scheme: {
            'balance_kopecks': reserve.get(scheme, 0),
            'pending_withdrawals_kopecks': pending_withdrawals.get(scheme, 0),
            'total_reserve_kopecks': reserve.get(scheme, 0) + pending_withdrawals.get(scheme, 0),
        }
        for scheme in REFERRAL_RATES_PERCENT
    }


# ИСПРАВЛЕНО 23.09.2026 (найдено при проверке логики оплат рефералов по
# просьбе пользователя): раньше это был статический словарь ТОЛЬКО с двумя
# схемами и вручную вписанными процентами - после появления схемы 'admin'
# (40/20/10%) её резерв (балансы + заявки на вывод по ней) молча пропадал
# из отчёта format_campaign_profit_text (цикл шёл по REFERRAL_SCHEME_LABELS,
# а не по REFERRAL_RATES_PERCENT) - "Итого резерв" был ЗАНИЖЕН на всю сумму
# схемы 'admin'. Плюс проценты юр.лица в подписи давно устарели (было
# 40/30/20%, стало 35/20/10%). Теперь подписи собираются ДИНАМИЧЕСКИ из
# самого REFERRAL_RATES_PERCENT - схему/проценты больше невозможно забыть
# поменять в двух местах.
REFERRAL_SCHEME_TITLES = {'individual': 'Обычная', 'legal_entity': 'Юр.лица', 'admin': 'Админ'}


def _referral_scheme_labels():
    return {
        scheme: f"{REFERRAL_SCHEME_TITLES.get(scheme, scheme)} ({'/'.join(str(p) for p in rates)}%)"
        for scheme, rates in REFERRAL_RATES_PERCENT.items()
    }


def format_campaign_profit_text():
    """Собирает текст отчёта сразу по двум периодам (всё время + текущий
    месяц) - см. compute_campaign_profit - плюс снимок резерва на выплаты
    рефералам по каждой схеме отдельно - см. compute_referral_reserve_by_scheme."""
    all_time = compute_campaign_profit('all')
    this_month = compute_campaign_profit('month')
    reserve = compute_referral_reserve_by_scheme()

    def _block(title, stats):
        return (
            f"<b>{title}</b>\n"
            f"Доход с подписок: {stats['subscription_revenue_kopecks'] / 100:,.0f}₽\n"
            f"Выплачено рефералам: -{stats['referral_payouts_kopecks'] / 100:,.0f}₽\n"
            f"Комиссия за вывод: +{stats['withdrawal_fee_income_kopecks'] / 100:,.0f}₽\n"
            f"<b>Чистая прибыль: {stats['net_profit_kopecks'] / 100:,.0f}₽</b>"
        ).replace(',', ' ')

    reserve_lines = []
    total_reserve = 0
    for scheme, label in _referral_scheme_labels().items():
        s = reserve[scheme]
        total_reserve += s['total_reserve_kopecks']
        reserve_lines.append(
            f"{label}: {s['total_reserve_kopecks'] / 100:,.0f}₽ "
            f"(на балансах {s['balance_kopecks'] / 100:,.0f}₽ + заявки на вывод {s['pending_withdrawals_kopecks'] / 100:,.0f}₽)"
        )
    reserve_block = (
        "<b>💼 Резерв на выплаты рефералам (сколько держать на счету)</b>\n"
        + "\n".join(reserve_lines)
        + f"\n<b>Итого резерв: {total_reserve / 100:,.0f}₽</b>"
    ).replace(',', ' ')

    return (
        "💰 <b>Прибыль кампании (все реферальные программы)</b>\n\n"
        + _block("За всё время", all_time)
        + "\n\n"
        + _block("Текущий месяц", this_month)
        + "\n\n"
        + reserve_block
    )


@router.message(Command("referral_paid"))
async def admin_mark_referral_paid(message: types.Message):
    """Админская команда - отмечает заявку выплаченной и уведомляет
    пользователя. Доступна только ADMIN_TELEGRAM_ID (переменная окружения) -
    без неё команда молчит (ничего не отвечает) для всех, это ожидаемо, пока
    админ не задаст свой Telegram ID в Railway Variables."""
    if not ADMIN_TELEGRAM_ID or str(message.from_user.id) != str(ADMIN_TELEGRAM_ID):
        return
    parts = (message.text or '').split()
    if len(parts) != 2 or not parts[1].isdigit():
        await message.answer("Использование: /referral_paid <id заявки>")
        return
    withdrawal_id = int(parts[1])
    result = mark_referral_withdrawal_paid(withdrawal_id)
    if not result:
        await message.answer("Заявка не найдена или уже обработана.")
        return
    await message.answer(f"Заявка #{withdrawal_id} отмечена как выплаченная.")
    try:
        await bot.send_message(
            result['user_id'],
            f"✅ Выплата {result['payout_kopecks'] / 100:.0f}₽ по заявке #{withdrawal_id} отправлена на карту."
        )
    except Exception:
        logger.warning(f"⚠️ Не удалось уведомить user_id={result['user_id']} о выплате #{withdrawal_id}")

